/** All translations for zizhitongjian ch.012 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起玄黓攝提格，盡昭陽赤奮若，凡十二年。", literal: "From Xuanji Shotige through Zhaoyang Chifenruo; twelve years in all.", idiomatic: "From Xuanji Shotige through Zhaoyang Chifenruo—twelve years in all." },
  { zh: "1冬，上東擊韓王信餘寇於東垣，過柏人。", literal: "1. In winter the sovereign went east to attack the remnant rebels of King Xin of Han at Dongyuan, passing Bo Ren.", idiomatic: "1. In winter the Emperor marched east against the remnant rebels of King Xin of Han at Dongyuan, passing through Bo Ren." },
  { zh: "貫高等壁人於廁中，欲以要上。", literal: "Guan Gao and others posted ambushers in the privy, intending to strike the sovereign there.", idiomatic: "Guan Gao and others posted assassins in the privy, intending to strike the Emperor there." },
  { zh: "上欲宿，心動，問曰：「縣名為何？", literal: "The sovereign wished to lodge for the night; his heart stirred, and he asked: \"What is this county called?", idiomatic: "The Emperor meant to lodge for the night; his heart stirred, and he asked: \"What is this county called?\"" },
  { zh: "」曰：「柏人。", literal: "\" They replied: \"Bo Ren.", idiomatic: "\" They said, \"Bo Ren.\"" },
  { zh: "」上曰：「柏人者，迫於人也。", literal: "\" The sovereign said: \"'Bo Ren' means one forced upon others.", idiomatic: "\" The Emperor said, \"'Bo Ren'—that is, one who forces himself upon others.\"" },
  { zh: "」遂不宿而去。", literal: "\" He then did not lodge but departed.", idiomatic: "\" He would not stay and went on." },
  { zh: "十二月，帝行自東垣至。", literal: "In the twelfth month the Emperor's procession returned from Dongyuan.", idiomatic: "In the twelfth month the Emperor's procession returned from Dongyuan." },
  { zh: "----2春，三月，行如洛陽。", literal: "----2 In spring, the third month, he traveled to Luoyang.", idiomatic: "----2 In spring, the third month, he traveled to Luoyang." },
  { zh: "----3令賈人毋得衣錦、繡、綺、縠、絺、紵、罽，操兵、乘、騎馬。", literal: "----3 An order: merchants must not wear brocade, embroidery, damask, fine gauze, ramie, hemp, or felt; carry arms; ride in chariots; or ride horses.", idiomatic: "----3 An edict forbade merchants to wear brocade, embroidery, damask, fine gauze, ramie, hemp, or felt, or to carry arms, ride in chariots, or ride horses." },
  { zh: "----4秋，九月，行自洛陽至；", literal: "----4 In autumn, the ninth month, his procession returned from Luoyang;", idiomatic: "----4 In autumn, the ninth month, his procession returned from Luoyang;" },
  { zh: "淮南王、梁王、趙王、楚王皆從。", literal: "the kings of Huainan, Liang, Zhao, and Chu all followed.", idiomatic: "and the kings of Huainan, Liang, Zhao, and Chu all followed." },
  { zh: "----5匈奴冒頓數苦北邊。", literal: "----5 Modu of the Xiongnu repeatedly harried the northern frontier.", idiomatic: "----5 Modu of the Xiongnu repeatedly harried the northern frontier." },
  { zh: "上患之，問劉敬，劉敬曰：「天下初定，士卒罷於兵，未可以武服也。", literal: "The sovereign was troubled by this and questioned Liu Jing; Liu Jing said: \"All under Heaven is newly settled; the troops are weary of war—it cannot yet be subdued by force of arms.", idiomatic: "The Emperor was troubled and asked Liu Jing. Liu Jing said: \"The realm is newly settled and the troops are weary of war—we cannot yet subdue them by force." },
  { zh: "冒頓殺父代立，妻群母，以力為威，未可以仁義說也。", literal: "Modu killed his father and seized the throne in his place, took his father's consorts to wife, and makes might his awe—he cannot be persuaded by benevolence and righteousness.", idiomatic: "Modu killed his father and seized the throne, took his father's consorts to wife, and rules by force alone—he will not heed benevolence or righteousness." },
  { zh: "獨可以計久遠，子孫為臣耳；", literal: "Only by a plan for the long term may his descendants become your subjects;", idiomatic: "Only a long-term design can make his descendants your subjects;" },
  { zh: "然恐陛下不能為。", literal: "yet I fear Your Majesty may not be able to do it.", idiomatic: "yet I fear Your Majesty may not be able to do it." },
  { zh: "」上曰：「奈何？", literal: "\" The sovereign said: \"What is to be done?", idiomatic: "\" The Emperor said, \"What then?\"" },
  { zh: "」對曰：「陛下誠能以適長公主妻之，厚奉遺之，彼必慕，以為閼氏，生子，必為太子。", literal: "\" He replied: \"If Your Majesty can truly give him the eldest princess by the proper wife in marriage, send her off with rich gifts, he will surely esteem her and make her khatun; when she bears a son, he will surely be made heir.", idiomatic: "\" He answered, \"If Your Majesty will give him the eldest princess by the proper wife, send her with rich gifts, he will surely esteem her and make her khatun; when she bears a son, that son will surely be heir." },
  { zh: "陛下以歲時漢所餘，彼所鮮，數問遺，因使辨士風諭以禮節。", literal: "Your Majesty, with what Han has in surplus each season and what they lack, should repeatedly send gifts, and send eloquent persuaders to instruct them in ritual and propriety by example.", idiomatic: "Each season send what Han has in surplus and they lack, again and again; send eloquent persuaders to teach them ritual and propriety by example." },
  { zh: "冒頓在，固為子婿；", literal: "While Modu lives, he will surely be your son-in-law;", idiomatic: "While Modu lives, he will be your son-in-law;" },
  { zh: "死，則外孫為單于；", literal: "when he dies, your grandson by a daughter will be chanyu;", idiomatic: "when he dies, your grandson will be chanyu;" },
  { zh: "豈嘗聞外孫敢與大父抗禮者哉！", literal: "who has ever heard of a grandson by a daughter daring to stand in rival ceremony with his mother's father!", idiomatic: "who has ever heard of a daughter's grandson daring to stand as equal to his mother's father!" },
  { zh: "可無戰以漸臣也。", literal: "You may make them subjects by degrees without fighting.", idiomatic: "You may make them subjects by degrees without fighting." },
  { zh: "若陛下不能遣長公主，而令宗室及後宮詐稱公主，彼知，不肯貴近，無益也。", literal: "If Your Majesty cannot send the eldest princess but orders kinsmen of the imperial clan and women of the inner palace to falsely call themselves princesses, when they know it they will not honor or draw near—and it will be of no use.", idiomatic: "If Your Majesty cannot send the eldest princess but has clansmen and palace women falsely pose as princesses, once they know it they will not honor or draw near—and it will do no good." },
  { zh: "」帝曰：「善！", literal: "\" The Emperor said: \"Excellent!", idiomatic: "\" The Emperor said, \"Excellent!\"" },
  { zh: "」欲遣長公主。", literal: "\" He wished to send the eldest princess.", idiomatic: "\" He meant to send the eldest princess." },
  { zh: "呂后日夜泣曰：「妾唯太子、一女，奈何棄之匈奴？", literal: "Empress Lü wept day and night, saying: \"Your handmaid has only the heir and one daughter—how can we cast her away to the Xiongnu?", idiomatic: "Empress Lü wept day and night: \"I have only the heir and one daughter—how can we cast her away to the Xiongnu?\"" },
  { zh: "」上竟不能遣。", literal: "\" The sovereign in the end could not send her.", idiomatic: "\" The Emperor in the end could not send her." },
  { zh: "----1冬，上取家人子名為長公主，以妻單于；", literal: "----1 In winter the sovereign took a family member's daughter, styled her the eldest princess, and gave her to the chanyu in marriage;", idiomatic: "----1 In winter the Emperor took a family member's daughter, styled her the eldest princess, and gave her to the chanyu in marriage;" },
  { zh: "使劉敬往結和親約。", literal: "he sent Liu Jing to conclude a treaty of harmonious kinship.", idiomatic: "and sent Liu Jing to conclude a treaty of harmonious kinship." },
  { zh: "::臣光曰：建信侯謂冒頓殘賊，不可以仁義說，而欲與為婚姻，何前後之相違也！", literal: ":: Your servant Guang says: The Marquis of Jianxin said Modu is a cruel bandit who cannot be persuaded by benevolence and righteousness, yet wished to ally with him by marriage—how self-contradictory before and after!", idiomatic: ":: Your servant Guang says: The Marquis of Jianxin called Modu a cruel bandit who could not be moved by benevolence and righteousness, yet wished to ally with him by marriage—how his words contradict themselves!" },
  { zh: "夫骨肉之恩，尊卑之敘，唯仁義之人為能知之；", literal: "The affection between flesh and bone, the order of honor and baseness—only men of benevolence and righteousness can know them;", idiomatic: "The bonds of flesh and bone, the order of honor and baseness—only men of benevolence and righteousness can truly know them;" },
  { zh: "奈何欲以此服冒頓哉！", literal: "how then could you wish to subdue Modu by this!", idiomatic: "how then could you hope to subdue Modu by this!" },
  { zh: "蓋上世帝王之御夷狄也，服則懷之以德，叛則震之以威，未聞與為婚姻也。", literal: "The emperors and kings of high antiquity in governing the Yi and Di: if they submitted they cherished them with virtue; if they rebelled they awed them with might—one has not heard of making marriage alliances with them.", idiomatic: "Emperors and kings of high antiquity governed the barbarians thus: if they submitted, they cherished them with virtue; if they rebelled, they awed them with might—one has never heard of marrying them." },
  { zh: "且冒頓視其父如禽獸而獵之，奚有於婦翁！", literal: "Moreover, Modu regarded his father as a beast to be hunted—what regard would he have for a father-in-law!", idiomatic: "Moreover, Modu treated his father as a beast to be hunted—what regard would he have for a father-in-law!" },
  { zh: "建信侯之術，固已疏矣；", literal: "The Marquis of Jianxin's stratagem was already loose indeed;", idiomatic: "The Marquis of Jianxin's stratagem was already feeble;" },
  { zh: "況魯元已為趙后，又可奪乎！", literal: "how much more when Yuan of Lu was already queen of Zhao—could she be taken away!", idiomatic: "and when Yuan of Lu was already queen of Zhao, could she even be taken away!" },
  { zh: "----2劉敬從匈奴來，因言：「匈奴河南白羊、樓煩王，去長安近者七百里，輕騎一日一夜可以至秦中。", literal: "----2 Liu Jing returned from the Xiongnu and therefore said: \"The kings of the White Sheep and Loufan south of the Yellow River among the Xiongnu are, at their nearest, seven hundred li from Chang'an; light horsemen in one day and one night can reach the heart of Qin.", idiomatic: "----2 Liu Jing returned from the Xiongnu and said: \"The White Sheep and Loufan kings of the Xiongnu south of the Yellow River lie, at their nearest, seven hundred li from Chang'an; light horsemen can reach the heart of Qin in a day and a night." },
  { zh: "秦中新破，少民，地肥饒，可益實。", literal: "The heart of Qin was newly broken and has few people; the land is rich and fertile—it can be filled and made solid.", idiomatic: "The heart of Qin was newly pacified and has few people, yet the land is rich and fertile—it can be filled and strengthened." },
  { zh: "夫諸侯初起時，非齊諸田、楚昭、屈、景莫能興。", literal: "When the feudal lords first rose, none but the Tians of Qi and the Zhao, Qu, and Jing of Chu could stir.", idiomatic: "When the lords first rose, none but the Tians of Qi and the Zhao, Qu, and Jing of Chu could stir." },
  { zh: "今陛下雖都關中，實少民，東有六國之強族，一日有變，陛下亦未得高枕而臥也。", literal: "Now Your Majesty, though you have made your capital in the passes, in truth has few people; eastward are the powerful clans of the Six States—if one day there is trouble, Your Majesty also cannot lay your head on a high pillow and sleep.", idiomatic: "Your Majesty has made his capital in the passes, yet in truth has few people; eastward stand the powerful clans of the Six States—if trouble comes one day, Your Majesty cannot sleep on a high pillow either." },
  { zh: "臣願陛下徙六國後及豪桀、名家居關中，無事可以備胡，諸侯有變，亦足率以東伐。", literal: "Your servant wishes Your Majesty to move the descendants of the Six States and heroes, champions, and eminent families to dwell in the passes; when there is no affair they can guard against the Hu; if the feudal lords have trouble, they are also enough to lead eastward in attack.", idiomatic: "Your servant wishes Your Majesty to move the descendants of the Six States, heroes, champions, and eminent families to dwell in the passes; in peace they can guard against the Hu, and if the lords rebel, they are enough to lead an eastern campaign." },
  { zh: "此強本弱末之術也。", literal: "This is the method of strengthening the root and weakening the branches.", idiomatic: "This is the method of strengthening the root and weakening the branches." },
  { zh: "」上曰：「善！", literal: "\" The sovereign said: \"Excellent!", idiomatic: "\" The Emperor said, \"Excellent!\"" },
  { zh: "」十一月，徙齊、楚大族昭氏、屈氏、景氏、懷氏、田氏五族及豪桀於關中，與利田、宅，凡十餘萬口。", literal: "\" In the eleventh month he moved the great clans of Qi and Chu—the Zhao, Qu, Jing, Huai, and Tian families, five clans—and heroes and champions to the passes, granting them profitable fields and dwellings; in all more than a hundred thousand mouths.", idiomatic: "\" In the eleventh month he moved the great clans of Qi and Chu—the Zhao, Qu, Jing, Huai, and Tian families, five clans—and heroes and champions to the passes, granting them profitable fields and dwellings—more than a hundred thousand people in all." },
  { zh: "----3十二月，上行如洛陽。", literal: "----3 In the twelfth month the sovereign traveled to Luoyang.", idiomatic: "----3 In the twelfth month the Emperor traveled to Luoyang." },
  { zh: "----4貫高怨家知其謀，上變告之。", literal: "----4 Guan Gao's enemies, learning of his plot, submitted a secret report.", idiomatic: "----4 Guan Gao's enemies, learning of his plot, submitted a secret report." },
  { zh: "於是上逮捕趙王及諸反者。", literal: "Thereupon the sovereign arrested the king of Zhao and all the rebels.", idiomatic: "Thereupon the Emperor arrested the king of Zhao and all the rebels." },
  { zh: "趙午等十餘人皆爭自剄，貫高獨怒罵曰：「誰令公為之？", literal: "Zhao Wu and more than ten others all strove to cut their own throats; Guan Gao alone raged and cursed, saying: \"Who ordered you gentlemen to do this?", idiomatic: "Zhao Wu and more than ten others all strove to cut their own throats; Guan Gao alone raged and cursed: \"Who ordered you to do this?" },
  { zh: "今王實無謀，而並捕王。", literal: "Now the king in truth had no plot, yet you seize the king together with us.", idiomatic: "The king in truth had no plot, yet you seize the king together with us." },
  { zh: "公等皆死，誰白王不反者？", literal: "When you gentlemen are all dead, who will declare for the king that he did not rebel?", idiomatic: "When you are all dead, who will declare to the world that the king did not rebel?" },
  { zh: "」乃轞車膠致，與王詣長安。", literal: "\" He then had a barred cart made fast with glue and went with the king to Chang'an.", idiomatic: "\" He then had a barred cart sealed with glue and went with the king to Chang'an." },
  { zh: "高對獄曰：「獨吾屬為之，王實不知。", literal: "Gao answered at trial: \"Only our sort did it; the king in truth did not know.", idiomatic: "Gao answered at trial: \"Only our sort did it; the king in truth did not know." },
  { zh: "」吏治，搒笞數千，刺剟，身無可擊者，終不復言。", literal: "\" The clerks prosecuted him; he was flogged with the stick thousands of times and stabbed and pierced until there was no place on his body left to strike—yet in the end he would not speak again.", idiomatic: "\" The clerks prosecuted him; he was flogged thousands of times and stabbed and pierced until no inch of flesh remained to strike—yet he would not speak again." },
  { zh: "呂后數言：「張王以公主故，不宜有此。", literal: "Empress Lü repeatedly said: \"Because of the princess, King Zhang ought not suffer this.", idiomatic: "Empress Lü pleaded again and again: \"For the princess's sake, King Zhang ought not suffer this.\"" },
  { zh: "」上怒曰：「使張敖據天下，豈少而女乎！", literal: "\" The sovereign said in anger: \"Had Zhang Ao possessed all under Heaven, would he have lacked your daughter!", idiomatic: "\" The Emperor said in anger: \"Had Zhang Ao possessed the realm, would he have lacked your daughter!\"" },
  { zh: "」不聽。", literal: "\" He would not listen.", idiomatic: "\" He would not listen." },
  { zh: "廷尉以貫高事辭聞。", literal: "The commandant of justice reported Guan Gao's case and testimony to the sovereign.", idiomatic: "The commandant of justice reported Guan Gao's case and testimony to the Emperor." },
  { zh: "上曰：「壯士！", literal: "The sovereign said: \"A valiant man!", idiomatic: "The Emperor said, \"A valiant man!" },
  { zh: "誰知者？", literal: "Who knows him?", idiomatic: "Who knows him?" },
  { zh: "以私問之。", literal: "Question him privately.", idiomatic: "Question him privately." },
  { zh: "」中大夫洩公曰：「臣之邑子，素知之，此固趙國立義不侵，為然諾者也。", literal: "\" Grandee Xie said: \"A man of my native place—I have long known him. He is indeed one who stands on righteousness in Zhao and will not be violated, a man who keeps his word.", idiomatic: "\" Grandee Xie said, \"A man of my native place—I have long known him. He is one who stands on righteousness in Zhao and keeps his word.\"" },
  { zh: "」上使洩公持節往問之箯輿前。", literal: "\" The sovereign sent Xie with credentials to question him before his bamboo litter.", idiomatic: "\" The Emperor sent Xie with credentials to question him before his bamboo litter." },
  { zh: "洩公與相勞苦，如生平歡，因問：「張王果有計謀不？", literal: "Xie exchanged greetings of hardship and toil with him as in former days' pleasure, and therefore asked: \"Did King Zhang truly have a plot or not?", idiomatic: "Xie exchanged greetings with him as in former days' friendship, then asked: \"Did King Zhang truly have a plot or not?\"" },
  { zh: "」高曰：「人情寧不各愛其父母、妻子乎？", literal: "\" Gao said: \"Would human nature not have each man love his own parents and wife and children?", idiomatic: "\" Gao said, \"Would any man not love his own parents, wife, and children?" },
  { zh: "今吾三族皆以論死，豈愛王過於吾親哉？", literal: "Now my three clans are all condemned to death—how could I love the king more than my own kin?", idiomatic: "Now my three clans are all condemned to death—how could I love the king more than my own kin?" },
  { zh: "顧為王實不反，獨吾等為之。", literal: "Only that the king in truth did not rebel—it was we alone who did it.", idiomatic: "Only that the king in truth did not rebel—it was we alone who did it." },
  { zh: "」具道本指所以為者、王不知狀。", literal: "\" He fully set forth the original intent, why they had acted, and how the king did not know the circumstances.", idiomatic: "\" He fully set forth their original intent, why they had acted, and that the king did not know." },
  { zh: "於是洩公入，具以報上。", literal: "Thereupon Xie entered and fully reported to the sovereign.", idiomatic: "Thereupon Xie entered and fully reported to the Emperor." },
  { zh: "春，正月，上赦趙王敖，廢為宣平侯，徒代王如意為趙王。", literal: "In spring, the first month, the sovereign pardoned King Ao of Zhao, deposed him as Marquis of Xuanping, and moved the king of Dai, Ruyi, to be king of Zhao.", idiomatic: "In spring, the first month, the Emperor pardoned King Ao of Zhao, reduced him to Marquis of Xuanping, and moved King Ruyi of Dai to Zhao." },
  { zh: "上賢貫高為人，使洩公具告之曰：「張王已出。", literal: "The sovereign admired Guan Gao's character and had Xie fully tell him: \"King Zhang has been released.", idiomatic: "The Emperor admired Guan Gao's character and had Xie tell him in full: \"King Zhang has been released.\"" },
  { zh: "」因赦貫高。", literal: "\" He therefore pardoned Guan Gao.", idiomatic: "\" He therefore pardoned Guan Gao." },
  { zh: "貫高喜曰：「吾王審出乎？", literal: "Guan Gao said in joy: \"Has my king truly been released?", idiomatic: "Guan Gao said joyfully, \"Has my king truly been released?\"" },
  { zh: "」洩公曰：「然。", literal: "\" Xie said: \"It is so.", idiomatic: "\" Xie said, \"It is so.\"" },
  { zh: "」洩公曰：「上多足下，故赦足下。", literal: "\" Xie said: \"The sovereign thinks much of you, and therefore pardoned you.", idiomatic: "\" Xie said, \"The Emperor thinks much of you, and therefore pardoned you.\"" },
  { zh: "」貫高曰：「所以不死，一身無餘者，白張王不反也。", literal: "\" Gao said: \"The reason I would not die though my body had nothing left was to declare that King Zhang did not rebel.", idiomatic: "\" Gao said, \"The reason I would not die though they left nothing of my body was to declare that King Zhang did not rebel." },
  { zh: "今王已出，吾責已塞，死不恨矣。", literal: "Now the king has been released; my charge is fulfilled—to die is without regret.", idiomatic: "Now the king is released and my charge fulfilled—to die is without regret." },
  { zh: "且人臣有篡弒之名，何面目復事上哉？", literal: "Moreover, a minister who bears the name of regicide—what face has he to serve the sovereign again?", idiomatic: "Moreover, a minister who bears the name of regicide—what face has he to serve the Emperor again?" },
  { zh: "縱上不殺我，我不愧於心乎？", literal: "Even if the sovereign did not kill me, would I not be ashamed in my heart?", idiomatic: "Even if the Emperor did not kill me, would I not be ashamed in my own heart?" },
  { zh: "」乃仰絕亢，遂死。", literal: "\" He then threw back his head and severed his throat, and died.", idiomatic: "\" He threw back his head and cut his throat, and died." },
  { zh: "::荀悅論曰：貫高首為亂謀，殺主之賊；", literal: ":: Xun Yue's discourse says: Guan Gao was first to plot rebellion—the assassin of his lord;", idiomatic: ":: Xun Yue writes: Guan Gao was first to plot rebellion—the assassin of his lord;" },
  { zh: "雖能證明其王，小亮不塞大逆，私行不贖公罪。", literal: "though he could prove his king innocent, a small brightness does not block a great rebellion; private conduct does not redeem public crime.", idiomatic: "though he could prove his king innocent, a small loyalty cannot offset a great crime; private conduct cannot redeem public guilt." },
  { zh: "《春秋》之義大居正，罪無赦可也。", literal: "The meaning of the Spring and Autumn Annals is that the great must dwell in the correct—his crime admits no pardon.", idiomatic: "The Spring and Autumn Annals holds that the great must dwell in the correct—his crime admits no pardon." },
  { zh: "::臣光曰：高祖驕以失臣，貫高狠以亡君。", literal: ":: Your servant Guang says: The High Ancestor through arrogance lost his ministers; Guan Gao through fierceness destroyed his lord.", idiomatic: ":: Your servant Guang says: The High Ancestor through arrogance lost his ministers; Guan Gao through fierceness destroyed his lord." },
  { zh: "使貫高謀逆者，高祖之過也；", literal: "That Guan Gao plotted rebellion was the High Ancestor's fault;", idiomatic: "That Guan Gao plotted rebellion was the High Ancestor's fault;" },
  { zh: "使張敖亡國者，貫高之罪也。", literal: "that Zhang Ao lost his state was Guan Gao's crime.", idiomatic: "that Zhang Ao lost his kingdom was Guan Gao's crime." },
  { zh: "----5詔：「丙寅前有罪，殊死已下，皆赦之。", literal: "----5 An edict: \"For crimes before bingyin, all from capital punishment downward are pardoned.", idiomatic: "----5 An edict: \"For crimes before bingyin, all from capital punishment downward are pardoned.\"" },
  { zh: "」----6二月，行自洛陽至。", literal: "\" ----6 In the second month his procession returned from Luoyang.", idiomatic: "\" ----6 In the second month his procession returned from Luoyang." },
  { zh: "----7初，上詔：「趙群臣賓客敢從張王者，皆族。", literal: "----7 At first the sovereign had decreed: \"Among the ministers and retainers of Zhao, any who dared follow King Zhang—all their clans.", idiomatic: "----7 At first the Emperor had decreed: \"Among the ministers and retainers of Zhao, any who dared follow King Zhang—their clans shall be extinguished." },
  { zh: "」郎中田叔、客孟舒皆處髡鉗為王家奴以從。", literal: "\" The gentleman-of-the-palace Tian Shu and the retainer Meng Shu both submitted to shaving and fetters to become household slaves of the king and followed.", idiomatic: "\" Gentleman-of-the-palace Tian Shu and retainer Meng Shu both submitted to shaving and fetters to become the king's household slaves and followed." },
  { zh: "及張敖既免，上賢田叔、孟舒等。", literal: "When Zhang Ao was released, the sovereign admired Tian Shu, Meng Shu, and the others.", idiomatic: "When Zhang Ao was released, the Emperor admired Tian Shu, Meng Shu, and the others." },
  { zh: "召見，與語，漢廷臣無能出其右者。", literal: "He summoned them for audience and spoke with them—none among the Han court ministers could surpass them.", idiomatic: "He summoned them and spoke with them—none among the Han court ministers could surpass them." },
  { zh: "上盡拜為郡守、諸侯相。", literal: "The sovereign appointed them all governors of commanderies and chancellors of feudal states.", idiomatic: "The Emperor appointed them all governors of commanderies and chancellors of feudal states." },
  { zh: "----8夏，六月，乙未晦，日有食之。", literal: "----8 In summer, the sixth month, on the last day of the cycle yiwei, there was an eclipse of the sun.", idiomatic: "----8 In summer, the sixth month, on the last day yiwei, there was a solar eclipse." },
  { zh: "----9是歲，更以丞相何為相國。", literal: "----9 This year the chancellor He was changed to Chancellor of State.", idiomatic: "----9 This year Chancellor He was made Chancellor of State." },
  { zh: "1夏，五月，太上皇崩於櫟陽宮。", literal: "1. In summer, the fifth month, the Grand Imperial Father died at the Liyang Palace.", idiomatic: "1. In summer, the fifth month, the Grand Imperial Father died at the Liyang Palace." },
  { zh: "秋，七月，癸卯，葬太上皇於萬年。", literal: "In autumn, the seventh month, on guimao, the Grand Imperial Father was buried at Wannian.", idiomatic: "In autumn, the seventh month, on guimao, the Grand Imperial Father was buried at Wannian." },
  { zh: "楚王、梁王皆來送葬。", literal: "The kings of Chu and Liang both came to attend the funeral.", idiomatic: "The kings of Chu and Liang both came to attend the funeral." },
  { zh: "赦櫟陽囚。", literal: "Prisoners at Liyang were pardoned.", idiomatic: "Prisoners at Liyang were pardoned." },
  { zh: "----2定陶戚姬有寵於上，生趙王如意。", literal: "----2. Consort Qi of Dingtao had the sovereign's favor and bore the king of Zhao, Ruyi.", idiomatic: "----2. Consort Qi of Dingtao had the Emperor's favor and bore the king of Zhao, Ruyi." },
  { zh: "上以太子仁弱，謂如意類己；", literal: "The sovereign, considering the heir apparent benevolent and weak, said that Ruyi resembled himself;", idiomatic: "The Emperor, finding the heir apparent benevolent and weak, said that Ruyi resembled him;" },
  { zh: "雖封為趙王，常留之長安。", literal: "though enfeoffed as king of Zhao, he constantly kept him at Chang'an.", idiomatic: "though enfeoffed as king of Zhao, constantly kept him at Chang'an." },
  { zh: "上之關東，戚姬常從，日夜啼泣，欲立其子。", literal: "When the sovereign went east of the passes, Consort Qi often followed, weeping day and night, wishing to establish her son.", idiomatic: "When the Emperor went east of the passes, Consort Qi often followed, weeping day and night, wishing to make her son heir." },
  { zh: "呂后年長，常留守，益疏。", literal: "Empress Lü was older and constantly remained to guard the capital, growing ever more estranged.", idiomatic: "Empress Lü was older and constantly remained to guard the capital, growing ever more estranged." },
  { zh: "上欲廢太子而立趙王，大臣爭之，皆莫能得。", literal: "The sovereign wished to depose the heir apparent and establish the king of Zhao; the great ministers contended against it, yet none could prevail.", idiomatic: "The Emperor wished to depose the heir apparent and establish the king of Zhao; the great ministers contended against it, yet none could prevail." },
  { zh: "御史大夫周昌廷爭之強，上問其說。", literal: "Grandee Secretary Zhou Chang contended strongly in court; the sovereign asked his reasoning.", idiomatic: "Grandee Secretary Zhou Chang contended strongly in court; the Emperor asked his reasoning." },
  { zh: "昌為人吃，又盛怒，曰：「臣口不能言，然臣期期知其不可！", literal: "Chang was a man who stuttered, and was moreover in great anger. He said: \"Your servant's mouth cannot speak, yet your servant ji-ji knows it cannot be done!", idiomatic: "Chang was a stutterer and was moreover in great anger. He said: \"Your servant's mouth cannot speak, yet your servant ji-ji knows it cannot be done!" },
  { zh: "陛下欲廢太子，臣期期不奉詔！", literal: "If Your Majesty wishes to depose the heir apparent, your servant ji-ji will not obey the edict!", idiomatic: "If Your Majesty wishes to depose the heir apparent, your servant ji-ji will not obey the edict!" },
  { zh: "」上欣然而笑。", literal: "\" The sovereign was pleased and laughed.", idiomatic: "\" The Emperor was pleased and laughed." },
  { zh: "呂后側耳於東廂聽，既罷，見昌，為跪謝，曰：「微君，太子幾廢！", literal: "Empress Lü listened with her ear at the side in the eastern wing. When it was over she saw Chang, knelt to thank him, and said: \"Without you, sir, the heir apparent would nearly have been deposed!", idiomatic: "Empress Lü listened from the eastern wing. When it was over she saw Chang, knelt to thank him, and said: \"Without you, sir, the heir apparent would nearly have been deposed!" },
  { zh: "時趙王年十歲，上憂萬歲之後不全也；", literal: "At that time the king of Zhao was ten years old; the sovereign worried that after ten thousand years he would not be kept whole;", idiomatic: "At that time the king of Zhao was ten years old; the Emperor worried that after his death Ruyi would not be kept safe;" },
  { zh: "符璽御史趙堯請為趙王置貴強相，及呂后、太子、群臣素所敬憚者。", literal: "Chief Clerk of Seals and Tallies Zhao Yao requested that for the king of Zhao there be set a noble and strong chancellor, and one whom the empress, the heir apparent, and the assembled ministers had always respected and feared.", idiomatic: "Chief Clerk of Seals and Tallies Zhao Yao requested a noble and strong chancellor for the king of Zhao—one whom the empress, the heir apparent, and the assembled ministers had always respected and feared." },
  { zh: "上曰：「誰可者？", literal: "The sovereign said: \"Who will do?", idiomatic: "The Emperor said: \"Who will do?\"" },
  { zh: "」堯曰：「御史大夫昌，其人也。", literal: "\" Yao said: \"Grandee Secretary Chang—that is the man.", idiomatic: "\" Yao said: \"Grandee Secretary Chang—that is the man.\"" },
  { zh: "」上乃以昌相趙，而以堯代昌為御史大夫。", literal: "\" The sovereign thereupon made Chang chancellor of Zhao and replaced Chang with Yao as Grandee Secretary.", idiomatic: "\" The Emperor thereupon made Chang chancellor of Zhao and replaced Chang with Yao as Grandee Secretary." },
  { zh: "----3初，上以陽夏侯陳豨為相國，監趙、代邊兵；", literal: "----3. Earlier, the sovereign had made Marquis of Yangxia Chen Xi chancellor of state, overseeing the border troops of Zhao and Dai;", idiomatic: "----3. Earlier, the Emperor had made Marquis of Yangxia Chen Xi chancellor of state, overseeing the border troops of Zhao and Dai;" },
  { zh: "豨過辭淮陰侯。", literal: "Xi, passing by, took leave of the Marquis of Huaiyin.", idiomatic: "Xi, passing by, took leave of the Marquis of Huaiyin." },
  { zh: "淮陰侯挈其手，辟左右，與之步於庭，仰天歎曰：「子可與言乎？", literal: "The Marquis of Huaiyin took his hand, cleared away attendants, and walked with him in the courtyard, sighing to Heaven: \"May I speak with you?", idiomatic: "The Marquis of Huaiyin took his hand, cleared away attendants, and walked with him in the courtyard, sighing to Heaven: \"May I speak with you?\"" },
  { zh: "」豨曰：「唯將軍令之！", literal: "\" Xi said: \"Only await the general's command!", idiomatic: "\" Xi said: \"Only await the general's command!\"" },
  { zh: "」淮陰侯曰：「公之所居，天下精兵處也；", literal: "\" The Marquis of Huaiyin said: \"Where you dwell is where the elite troops of All under Heaven are;", idiomatic: "\" The Marquis of Huaiyin said: \"Where you dwell is where the elite troops of all under Heaven are;" },
  { zh: "而公，陛下之信幸臣也。", literal: "and you, sir, are a trusted and favored subject of Your Majesty.", idiomatic: "and you, sir, are a trusted and favored subject of Your Majesty." },
  { zh: "人言公之畔，陛下必不信；", literal: "If men say you have rebelled, Your Majesty will surely not believe it;", idiomatic: "If men say you have rebelled, Your Majesty will surely not believe it;" },
  { zh: "再至，陛下乃疑矣；", literal: "a second time, Your Majesty will then suspect;", idiomatic: "a second time, Your Majesty will then suspect;" },
  { zh: "三至，必怒而自將。", literal: "a third time, he will surely be angry and lead the army himself.", idiomatic: "a third time, he will surely be angry and lead the army himself." },
  { zh: "吾為公從中起，天下可圖也。", literal: "I will rise for you from within; All under Heaven may be plotted for.", idiomatic: "I will rise for you from within; all under Heaven may be taken." },
  { zh: "」陳豨素知其能也，信之，曰：「謹奉教！", literal: "\" Chen Xi had always known his ability and trusted him, saying: \"I respectfully receive your instruction!", idiomatic: "\" Chen Xi had always known his ability and trusted him, saying: \"I respectfully receive your instruction!\"" },
  { zh: "豨常慕魏無忌之養士，及為相守邊，告歸，過趙，賓客隨之者千餘乘，邯鄲官舍皆滿。", literal: "Xi had always admired Lord Xinling of Wei's nurturing of knights. When he became chancellor and guarded the border, on requesting leave to return he passed through Zhao; retainers following him numbered more than a thousand chariots, and the official lodgings of Handan were all full.", idiomatic: "Xi had always admired Lord Xinling of Wei's nurturing of knights. When he became chancellor and guarded the border, on requesting leave to return he passed through Zhao; retainers following him numbered more than a thousand chariots, and the official lodgings of Handan were all full." },
  { zh: "趙相周昌求入見上，具言豨賓客甚盛，擅兵於外數歲，恐有變。", literal: "Zhao's chancellor Zhou Chang sought to enter and see the sovereign, reporting fully that Xi's retainers were very numerous, that he had monopolized troops abroad for several years, and that there might be a change.", idiomatic: "Zhao's chancellor Zhou Chang sought audience with the Emperor, reporting fully that Xi's retainers were very numerous, that he had held troops abroad for several years, and that there might be trouble." },
  { zh: "上令人覆案豨客居代者諸不法事，多連引豨。", literal: "The sovereign sent men to re-investigate the various unlawful matters of Xi's guests dwelling in Dai; many implicated Xi.", idiomatic: "The Emperor sent men to re-investigate unlawful matters involving Xi's guests in Dai; many implicated Xi." },
  { zh: "豨恐，韓王信因使王黃、曼丘臣等說誘之。", literal: "Xi was afraid; the king of Han Xin thereupon sent Wang Huang, Manqiu Chen, and others to persuade and entice him.", idiomatic: "Xi was afraid; Han Xin the king of Han sent Wang Huang, Manqiu Chen, and others to persuade and entice him." },
  { zh: "太上皇崩，上使人召豨，豨稱病不至；", literal: "The Grand Supreme Sovereign died; the sovereign sent men to summon Xi, but Xi claimed illness and did not come;", idiomatic: "The Grand Supreme Sovereign died; the Emperor sent men to summon Xi, but Xi claimed illness and did not come;" },
  { zh: "九月，遂與王黃等反，自立為代王，劫略趙、代。", literal: "in the ninth month he thereupon rebelled with Wang Huang and others, declared himself king of Dai, and plundered Zhao and Dai.", idiomatic: "in the ninth month he rebelled with Wang Huang and others, declared himself king of Dai, and plundered Zhao and Dai." },
  { zh: "上自東擊之。", literal: "The sovereign himself went east to attack him.", idiomatic: "The Emperor himself went east to attack him." },
  { zh: "至邯鄲，喜曰：「豨不南據邯鄲而阻漳水，吾知其無能為矣。", literal: "Reaching Handan, he was pleased and said: \"Xi did not seize Handan to the south and block the Zhang River—I know he can do nothing.", idiomatic: "Reaching Handan, he was pleased and said: \"Xi did not seize Handan to the south and block the Zhang River—I know he can do nothing.\"" },
  { zh: "周昌奏：「常山二十五城，亡其二十城；", literal: "Zhou Chang memorialized: \"Of Changshan's twenty-five cities, twenty are lost;", idiomatic: "Zhou Chang memorialized: \"Of Changshan's twenty-five cities, twenty are lost;" },
  { zh: "請誅守、尉。", literal: "I request that the governors and commandants be executed.", idiomatic: "I request that the governors and commandants be executed.\"" },
  { zh: "」上曰：「守、尉反乎？", literal: "\" The sovereign said: \"Did the governors and commandants rebel?", idiomatic: "\" The Emperor said: \"Did the governors and commandants rebel?\"" },
  { zh: "」對曰：「不。", literal: "\" He replied: \"No.", idiomatic: "\" He replied: \"No.\"" },
  { zh: "」上曰：「是力不足，亡罪。", literal: "\" The sovereign said: \"Their strength was insufficient—no crime.", idiomatic: "\" The Emperor said: \"Their strength was insufficient—no crime.\"" },
  { zh: "上令周昌選趙壯士可令將者，白見四人。", literal: "The sovereign ordered Zhou Chang to select stalwart men of Zhao fit to be made generals; he reported and presented four men.", idiomatic: "The Emperor ordered Zhou Chang to select stalwart men of Zhao fit to be made generals; he presented four men." },
  { zh: "上嫚罵曰：「豎子能為將乎？", literal: "The sovereign insulted and reviled them, saying: \"Can striplings be generals?", idiomatic: "The Emperor insulted and reviled them: \"Can striplings be generals?\"" },
  { zh: "」四人慚，皆伏地；", literal: "\" The four were ashamed and all prostrated themselves;", idiomatic: "\" The four were ashamed and all prostrated themselves;" },
  { zh: "上封各千戶，以為將。", literal: "the sovereign enfeoffed each with a thousand households and made them generals.", idiomatic: "the Emperor enfeoffed each with a thousand households and made them generals." },
  { zh: "左右諫曰；", literal: "Attendants at his side remonstrated, saying:", idiomatic: "Attendants at his side remonstrated:" },
  { zh: "「從入蜀、漢，伐楚，賞未遍行；", literal: "\"From entering Shu and Han, attacking Chu, rewards have not yet been fully carried out;", idiomatic: "\"From entering Shu and Han and attacking Chu, rewards have not yet been fully carried out;" },
  { zh: "今封此，何功？", literal: "now you enfeoff these—what merit?", idiomatic: "now you enfeoff these—what merit?\"" },
  { zh: "」上曰：「非汝所知。", literal: "\" The sovereign said: \"This is not for you to know.", idiomatic: "\" The Emperor said: \"This is not for you to know." },
  { zh: "陳豨反，趙、代地皆豨有。", literal: "Chen Xi has rebelled; the lands of Zhao and Dai are all in Xi's possession.", idiomatic: "Chen Xi has rebelled; the lands of Zhao and Dai are all in Xi's possession." },
  { zh: "吾以羽檄征天下兵，未有至者，今計唯獨邯鄲中兵耳。", literal: "I have summoned the troops of All under Heaven with urgent dispatch, yet none have arrived; at present the plan relies only on the troops within Handan.", idiomatic: "I have summoned the troops of all under Heaven with urgent dispatch, yet none have arrived; at present the plan relies only on the troops within Handan." },
  { zh: "吾何愛四千戶，不以慰趙子弟！", literal: "Why should I begrudge four thousand households and not use them to comfort the youths of Zhao!", idiomatic: "Why should I begrudge four thousand households and not use them to comfort the youths of Zhao!\"" },
  { zh: "」皆曰：「善！", literal: "\" All said: \"Excellent!", idiomatic: "\" All said: \"Excellent!\"" },
  { zh: "又聞豨將皆故賈人，上曰：「吾知所以與之矣。", literal: "He also heard that Xi's generals were all former merchants. The sovereign said: \"I know how to deal with them.", idiomatic: "He also heard that Xi's generals were all former merchants. The Emperor said: \"I know how to deal with them.\"" },
  { zh: "」乃多以金購豨將，豨將多降。", literal: "\" He thereupon used much gold to buy over Xi's generals; many of Xi's generals surrendered.", idiomatic: "\" He thereupon used much gold to buy over Xi's generals; many of Xi's generals surrendered." },
  { zh: "----1冬，上在邯鄲。", literal: "----1. In winter the sovereign was at Handan.", idiomatic: "----1. In winter the Emperor was at Handan." },
  { zh: "陳豨將侯敞將萬餘人遊行，王黃將騎千餘軍曲逆，張春將卒萬餘人渡河攻聊城。", literal: "Chen Xi's general Hou Chang led more than ten thousand men on the march; Wang Huang led more than a thousand horsemen and encamped at Quyi; Zhang Chun led more than ten thousand soldiers across the river to attack Liaocheng.", idiomatic: "Chen Xi's general Hou Chang led more than ten thousand men on the march; Wang Huang led more than a thousand horsemen and encamped at Quyi; Zhang Chun led more than ten thousand soldiers across the river to attack Liaocheng." },
  { zh: "漢將軍郭蒙與齊將擊，大破之。", literal: "Han general Guo Meng joined with a Qi general to attack and inflicted a great defeat.", idiomatic: "Han general Guo Meng joined with a Qi general to attack and inflicted a great defeat." },
  { zh: "太尉周勃道太原入定代地，至馬邑，不下，攻殘之。", literal: "Grand Commandant Zhou Bo went by way of Taiyuan to settle Dai; reaching Mayi, it would not submit, so he attacked and ravaged it.", idiomatic: "Grand Commandant Zhou Bo went by way of Taiyuan to settle Dai; reaching Mayi, it would not submit, so he attacked and ravaged it." },
  { zh: "趙利守東垣，帝攻拔之，更命曰真定。", literal: "Zhao Li held Dongyuan; the Emperor attacked and took it and renamed it Zhending.", idiomatic: "Zhao Li held Dongyuan; the Emperor attacked and took it and renamed it Zhending." },
  { zh: "帝購王黃、曼丘臣以千金，其麾下皆生致之。", literal: "The Emperor offered a thousand in gold for Wang Huang and Manqiu Chen; their subordinates were all captured alive and delivered.", idiomatic: "The Emperor offered a thousand in gold for Wang Huang and Manqiu Chen; their subordinates were all captured alive and delivered." },
  { zh: "於是陳豨軍遂敗。", literal: "Thereupon Chen Xi's army was defeated.", idiomatic: "Thereupon Chen Xi's army was defeated." },
  { zh: "淮陰侯信稱病，不從擊豨，陰使人至豨所，與通謀。", literal: "The Marquis of Huaiyin Xin claimed illness and did not follow in attacking Xi, but secretly sent men to Xi's place to communicate in conspiracy.", idiomatic: "The Marquis of Huaiyin Xin claimed illness and did not follow in attacking Xi, but secretly sent men to Xi's camp to conspire with him." },
  { zh: "信謀與家臣夜詐詔赦諸官徒、奴，欲發以襲呂后、太子；", literal: "Xin plotted with household retainers by night to forge an edict pardoning all convict laborers and slaves, intending to raise them to strike Empress Lü and the heir apparent;", idiomatic: "Xin plotted with household retainers by night to forge an edict pardoning all convict laborers and slaves, intending to raise them to strike Empress Lü and the heir apparent;" },
  { zh: "部署已定，待豨報。", literal: "the deployment was already settled, awaiting Xi's report.", idiomatic: "the deployment was already settled, awaiting Xi's report." },
  { zh: "其舍人得罪於信，信囚，欲殺之。", literal: "A house steward had offended Xin; Xin imprisoned him and wished to kill him.", idiomatic: "A house steward had offended Xin; Xin imprisoned him and wished to kill him." },
  { zh: "春，正月，舍人弟上變，告信欲反狀於呂后。", literal: "In spring, the first month, the steward's younger brother reported the emergency, informing Empress Lü of Xin's intended rebellion.", idiomatic: "In spring, the first month, the steward's younger brother reported the emergency, informing Empress Lü of Xin's intended rebellion." },
  { zh: "呂后欲召，恐其儻不就，乃與蕭相國謀，詐令人從上所來，言豨已得，死，列侯、群臣皆賀。", literal: "Empress Lü wished to summon him but feared that perhaps he would not come; she therefore plotted with Chancellor Xiao, falsely sending a man from where the sovereign was, saying that Xi had been taken and was dead, and that marquises and assembled ministers all congratulated.", idiomatic: "Empress Lü wished to summon him but feared he might not come; she plotted with Chancellor Xiao, falsely sending a man from the Emperor's camp saying that Xi had been taken and was dead, and that marquises and assembled ministers all congratulated." },
  { zh: "相國紿信曰：「雖疾，強入賀。", literal: "The chancellor deceived Xin, saying: \"Though ill, force yourself to enter and congratulate.", idiomatic: "The chancellor deceived Xin: \"Though ill, force yourself to enter and congratulate.\"" },
  { zh: "」信入，呂后使武士縛信，斬之長樂鐘室。", literal: "\" Xin entered; Empress Lü had warriors bind Xin and behead him in the Bell Room of Changle.", idiomatic: "\" Xin entered; Empress Lü had warriors bind Xin and behead him in the Bell Room of Changle." },
  { zh: "信方斬，曰：「吾悔不用蒯徹之計，乃為兒女子所詐，豈非天哉？", literal: "As Xin was about to be beheaded he said: \"I regret not using Kuai Che's plan—to be deceived by women and children, is this not Heaven's doing?", idiomatic: "As Xin was about to be beheaded he said: \"I regret not using Kuai Che's plan—to be deceived by women and children, is this not Heaven's doing?\"" },
  { zh: "」遂夷信三族。", literal: "\" He thereupon exterminated Xin's three clans.", idiomatic: "\" He thereupon exterminated Xin's three clans." },
  { zh: "::臣光曰：世或以韓信為首建大策，與高祖起漢中，定三秦，遂分兵以北，禽魏，取代，僕趙，脅燕，東擊齊而有之，南滅楚垓下，漢之所以得天下者，大抵皆信之功也。", literal: ":: Your servant Guang says: The age sometimes takes Han Xin as the first to frame the great design, rising with the High Ancestor from Hanzhong, settling the Three Qins, then dividing troops northward—capturing Wei, taking Dai, subduing Zhao, coercing Yan, striking east to take Qi, and south destroying Chu at Gaixia. That Han won All under Heaven was, broadly speaking, mostly Xin's achievement.", idiomatic: ":: Your servant Guang says: The age sometimes takes Han Xin as the first to frame the great design, rising with the High Ancestor from Hanzhong, settling the Three Qins, then dividing troops northward—capturing Wei, taking Dai, subduing Zhao, coercing Yan, striking east to take Qi, and south destroying Chu at Gaixia. That Han won all under Heaven was, broadly speaking, mostly Xin's achievement." },
  { zh: "觀其距蒯徹之說，迎高祖於陳，豈有反心哉？", literal: "Observing how he rejected Kuai Che's counsel yet received the High Ancestor at Chen—how could he have had a rebellious heart?", idiomatic: "Observing how he rejected Kuai Che's counsel yet received the High Ancestor at Chen—how could he have had a rebellious heart?" },
  { zh: "良由失職怏怏，遂陷悖逆。", literal: "It was truly because, losing his post, he was resentful and discontented, and so fell into rebellion.", idiomatic: "It was truly because, losing his post, he was resentful and discontented, and so fell into rebellion." },
  { zh: "夫以盧綰里閈舊恩，猶南面王燕，信乃以列侯奉朝請，豈非高祖亦有負於信哉？", literal: "That Lu Wan, through old neighborhood kindness, still faced south as king of Yan, while Xin merely as a ranked marquis attended court—is this not that the High Ancestor too had wronged Xin?", idiomatic: "That Lu Wan, through old neighborhood ties, still faced south as king of Yan, while Xin merely as a ranked marquis attended court—is this not that the High Ancestor too had wronged Xin?" },
  { zh: "臣以為高祖用詐謀禽信於陳，言負則有之；", literal: "Your servant considers that the High Ancestor used deceitful stratagems to capture Xin at Chen—to speak of wronging him is so;", idiomatic: "Your servant considers that the High Ancestor used deceitful stratagems to capture Xin at Chen—to speak of wronging him is so;" },
  { zh: "雖然，信亦有以取之也。", literal: "even so, Xin too had grounds on which he brought it upon himself.", idiomatic: "even so, Xin too had grounds on which he brought it upon himself." },
  { zh: "始，漢與楚相距滎陽，信滅齊，不還報而自王；", literal: "At the beginning, when Han and Chu faced each other at Yingyang, Xin destroyed Qi, did not return to report, and made himself king;", idiomatic: "At the beginning, when Han and Chu faced each other at Yingyang, Xin destroyed Qi, did not return to report, and made himself king;" },
  { zh: "其後漢追楚至固陵，與信期共攻楚而信不至。", literal: "afterward Han pursued Chu to Guling and fixed a date with Xin to attack Chu together, yet Xin did not come.", idiomatic: "afterward Han pursued Chu to Guling and fixed a date with Xin to attack Chu together, yet Xin did not come." },
  { zh: "當是之時，高祖固有取信之心矣，顧力不能耳。", literal: "At that time the High Ancestor already had a mind to take Xin in, only his strength was insufficient.", idiomatic: "At that time the High Ancestor already had a mind to take Xin in, only his strength was insufficient." },
  { zh: "及天下已定，則信復何恃哉？", literal: "When All under Heaven was already settled, what could Xin again rely upon?", idiomatic: "When all under Heaven was already settled, what could Xin again rely upon?" },
  { zh: "夫乘時以徼利者，市井之志也；", literal: "To seize the moment and seek profit is the ambition of the marketplace;", idiomatic: "To seize the moment and seek profit is the ambition of the marketplace;" },
  { zh: "酬功而報德者，士君子之心也。", literal: "to repay merit and return kindness is the heart of the gentleman and scholar.", idiomatic: "to repay merit and return kindness is the heart of the gentleman and scholar." },
  { zh: "信以市井之志利其身，而以君子之心望於人，不亦難哉？", literal: "Xin used the marketplace ambition to profit himself, yet with the gentleman's heart expected it of others—is this not difficult?", idiomatic: "Xin used the marketplace ambition to profit himself, yet with the gentleman's heart expected it of others—is this not difficult?" },
  { zh: "是故太史公論之曰：「假令韓信學道謙讓，不伐己功，不矜其能，則庶幾哉？", literal: "Therefore the Grand Historian judged, saying: \"Suppose Han Xin had studied the Way, been modest and yielding, not boasted of his own merit, not prided himself on his ability—then might he not have fared thus?", idiomatic: "Therefore the Grand Historian judged: \"Suppose Han Xin had studied the Way, been modest and yielding, not boasted of his own merit, not prided himself on his ability—then might he not have fared thus?" },
  { zh: "於漢家勳，可以比周、召、太公之徒，後世血食矣！", literal: "Among Han's meritorious servants he could have been compared to the Duke of Zhou, the Duke of Shao, and Grand Duke Jiang, and later ages would have offered blood sacrifice!", idiomatic: "Among Han's meritorious servants he could have been compared to the Duke of Zhou, the Duke of Shao, and Grand Duke Jiang, and later ages would have offered blood sacrifice!" },
  { zh: "不務出此，而天下已集，乃謀畔逆；", literal: "Not pursuing this course, yet when All under Heaven was already gathered he plotted rebellion;", idiomatic: "Not pursuing this course, yet when all under Heaven was already gathered he plotted rebellion;" },
  { zh: "夷滅宗族，不亦宜乎？", literal: "to exterminate his clan—was it not fitting?", idiomatic: "to exterminate his clan—was it not fitting?\"" },
  { zh: "」----2將軍柴武斬韓王信於參合。", literal: "\" ----2. General Chai Wu beheaded the king of Han Xin at Canhe.", idiomatic: "\" ----2. General Chai Wu beheaded Han Xin the king of Han at Canhe." },
  { zh: "----3上還洛陽，聞淮陰侯之死，且喜且憐之，問呂后曰：「信死亦何言？", literal: "----3. The sovereign returned to Luoyang. Hearing of the Marquis of Huaiyin's death, he was both pleased and pitying, and asked Empress Lü: \"What did Xin say at his death?", idiomatic: "----3. The Emperor returned to Luoyang. Hearing of the Marquis of Huaiyin's death, he was both pleased and pitying, and asked Empress Lü: \"What did Xin say at his death?\"" },
  { zh: "」呂后曰：「信言恨不用蒯徹計。", literal: "\" Empress Lü said: \"Xin said he regretted not using Kuai Che's plan.", idiomatic: "\" Empress Lü said: \"Xin said he regretted not using Kuai Che's plan.\"" },
  { zh: "」上曰：「是齊辯士蒯徹也。", literal: "\" The sovereign said: \"That is Kuai Che the persuader of Qi.", idiomatic: "\" The Emperor said: \"That is Kuai Che the persuader of Qi.\"" },
  { zh: "」乃詔齊捕蒯徹。", literal: "\" He thereupon edicted Qi to arrest Kuai Che.", idiomatic: "\" He thereupon edicted Qi to arrest Kuai Che." },
  { zh: "蒯徹至，上曰：「若教淮陰侯反乎？", literal: "When Kuai Che arrived, the sovereign said: \"Did you teach the Marquis of Huaiyin to rebel?", idiomatic: "When Kuai Che arrived, the Emperor said: \"Did you teach the Marquis of Huaiyin to rebel?\"" },
  { zh: "」對曰：「然，臣固教之。", literal: "\" He replied: \"Yes—I indeed taught him.", idiomatic: "\" He replied: \"Yes—I indeed taught him." },
  { zh: "豎子不用臣之策，故令自夷於此。", literal: "The stripling did not use your servant's stratagem, and so caused himself to be exterminated here.", idiomatic: "The stripling did not use my stratagem, and so caused himself to be exterminated here." },
  { zh: "如用臣之計，陛下安得而夷之乎？", literal: "Had he used your servant's plan, how could Your Majesty have exterminated him?", idiomatic: "Had he used my plan, how could Your Majesty have exterminated him?\"" },
  { zh: "」上怒曰：「烹之！", literal: "\" The sovereign angrily said: \"Boil him!", idiomatic: "\" The Emperor angrily said: \"Boil him!\"" },
  { zh: "」徹曰：「嗟乎！", literal: "\" Che said: \"Alas!", idiomatic: "\" Che said: \"Alas!" },
  { zh: "冤哉烹也！", literal: "To be boiled is a grievous wrong!", idiomatic: "To be boiled is a grievous wrong!" },
  { zh: "」上曰：「君教韓信反，何冤？", literal: "\" The sovereign said: \"You taught Han Xin to rebel—what wronged suffering is this?", idiomatic: "\" The Emperor said: \"You taught Han Xin to rebel—what wrong is there in boiling you?" },
  { zh: "」對曰：「秦失其鹿，天下共逐之，高材疾足者先得焉。", literal: "\" He replied: \"Qin lost its deer; all under Heaven joined in the chase, and those of tall talent and swift feet got it first.", idiomatic: "\" He replied: \"Qin lost the realm; all under Heaven joined the chase, and those of greatest talent and swiftest feet seized it first." },
  { zh: "跖之狗吠堯，堯非不仁，狗固吠非其主。", literal: "Zhi's dog barked at Yao—Yao was not unkind; dogs naturally bark at those who are not their master.", idiomatic: "Zhi's dog barked at Yao—Yao was not unkind; dogs naturally bark at anyone who is not their master." },
  { zh: "當是時，臣唯獨知韓信，非知陛下也。", literal: "At that time your servant knew only Han Xin, not Your Majesty.", idiomatic: "At that time I knew only Han Xin, not Your Majesty." },
  { zh: "且天下銳精持鋒欲為陛下所為者甚眾，顧力不能耳，又可盡烹之邪？", literal: "Moreover, those under Heaven who sharpen their essence and hold their blades wishing to do what Your Majesty has done are many—only that their strength cannot; could you boil them all?", idiomatic: "Moreover, countless men under Heaven sharpen their wits and grip their blades wishing to do what Your Majesty has done—only that their strength fails; could you boil them all?" },
  { zh: "」上曰：「置之。", literal: "\" The sovereign said: \"Let it be.\"", idiomatic: "\" The Emperor said: \"Let it go.\"" },
  { zh: "」----4立子恆為代王，都晉陽。", literal: "\" ----4 He established his son Heng as King of Dai, with his capital at Jinyang.", idiomatic: "\" ----4 He made his son Heng King of Dai, with his capital at Jinyang." },
  { zh: "----5大赦天下。", literal: "----5 A general amnesty was proclaimed for all under Heaven.", idiomatic: "----5 A general amnesty was proclaimed for the realm." },
  { zh: "----6上之擊陳豨也，徵兵於梁；", literal: "----6 When the sovereign was campaigning against Chen Xi, he called up troops from Liang;", idiomatic: "----6 When the Emperor campaigned against Chen Xi, he called up troops from Liang;" },
  { zh: "梁王稱病，使將將兵詣邯鄲。", literal: "the King of Liang pleaded illness and sent a general to lead troops to Handan.", idiomatic: "the King of Liang pleaded illness and sent a general to lead troops to Handan." },
  { zh: "上怒，使人讓之。", literal: "The sovereign was angry and sent a man to rebuke him.", idiomatic: "The Emperor was angry and sent a man to rebuke him." },
  { zh: "梁王恐，欲自往謝。", literal: "The King of Liang was afraid and wished to go in person to apologize.", idiomatic: "The King of Liang was afraid and wished to go in person to apologize." },
  { zh: "其將扈輒曰：「王始不往，見讓而往，往則為禽矣。", literal: "His general Hu Zhe said: \"Your Majesty at first did not go; now, rebuked, if you go, you will be seized.", idiomatic: "His general Hu Zhe said: \"Your Majesty at first did not go; now, rebuked, if you go you will be seized." },
  { zh: "不如遂發兵反。", literal: "Better to raise troops and rebel at once.", idiomatic: "Better to raise troops and rebel at once." },
  { zh: "」梁王不聽。", literal: "\" The King of Liang did not listen.", idiomatic: "\" The King of Liang did not listen." },
  { zh: "梁太僕得罪，亡走漢，告梁王與扈輒謀反。", literal: "The Grand Steward of Liang offended and fled to Han, reporting that the King of Liang and Hu Zhe were plotting rebellion.", idiomatic: "The Grand Steward of Liang offended someone, fled to Han, and reported that the King of Liang and Hu Zhe were plotting rebellion." },
  { zh: "於是上使使掩梁王，梁王不覺，遂囚之洛陽。", literal: "Thereupon the sovereign sent envoys to seize the King of Liang; the King of Liang did not perceive it and was imprisoned at Luoyang.", idiomatic: "Thereupon the Emperor sent envoys to seize the King of Liang; he did not perceive it and was imprisoned at Luoyang." },
  { zh: "有司治「反形已具，請論如法」，上赦以為庶人，傳處蜀青衣。", literal: "The relevant officials prosecuted that \"the marks of rebellion are complete; we request judgment according to law\"; the sovereign pardoned him and made him a commoner, sending him under escort to Qingyi in Shu.", idiomatic: "The relevant officials prosecuted that \"the marks of rebellion are complete; we request judgment according to law\"; the Emperor pardoned him and made him a commoner, sending him under escort to Qingyi in Shu." },
  { zh: "西至鄭，逢呂后從長安來。", literal: "Going west he reached Zheng and met the Empress Lü coming from Chang'an.", idiomatic: "Going west he reached Zheng and met Empress Lü coming from Chang'an." },
  { zh: "彭王為呂后泣涕，自言無罪，願處故昌邑。", literal: "The King of Peng wept for the Empress Lü and said himself guiltless, wishing to dwell at his former Changyi.", idiomatic: "King Peng wept before Empress Lü, declared himself guiltless, and asked to remain at his former seat of Changyi." },
  { zh: "呂后許諾，與俱東。", literal: "The Empress Lü promised and went east together with him.", idiomatic: "Empress Lü promised and traveled east with him." },
  { zh: "至洛陽，呂后白上曰：「彭王壯士，今徙之蜀，此自遺患；", literal: "Reaching Luoyang, the Empress Lü told the sovereign: \"The King of Peng is a stalwart man; now exiling him to Shu—this is to leave trouble for oneself;", idiomatic: "Reaching Luoyang, Empress Lü told the Emperor: \"King Peng is a stalwart man; exiling him to Shu now is to leave trouble for yourself;" },
  { zh: "不如遂誅之。", literal: "better to execute him at once.", idiomatic: "better to execute him at once." },
  { zh: "妾謹與俱來。", literal: "Your handmaid has deliberately come with him.\"", idiomatic: "I have deliberately brought him with me.\"" },
  { zh: "」於是呂后乃令其舍人告彭越復謀反。", literal: "\" Thereupon the Empress Lü had her house steward report that Peng Yue was again plotting rebellion.", idiomatic: "\" Thereupon Empress Lü had her house steward report that Peng Yue was plotting rebellion again." },
  { zh: "廷尉王恬關奏請族之，上可其奏。", literal: "Minister of Justice Wang Tian Guan memorialized requesting extinction of his clan; the sovereign approved the memorial.", idiomatic: "Minister of Justice Wang Tian Guan memorialized requesting extinction of his clan; the Emperor approved the memorial." },
  { zh: "三月，夷越三族。", literal: "In the third month, the house of Yue was extinguished to the third degree.", idiomatic: "In the third month, Peng Yue's clan was extinguished to the third degree." },
  { zh: "梟越首洛陽，下詔：「有收視者，輒捕之。", literal: "Yue's head was displayed at Luoyang; an edict: \"Whoever collects and views it shall be arrested at once.", idiomatic: "Peng Yue's head was displayed at Luoyang; an edict: \"Whoever collects and views it shall be arrested at once." },
  { zh: "梁大夫欒布使於齊，還，奏事越頭下，祠而哭之。", literal: "A great officer of Liang, Luan Bu, had been envoy to Qi; returning, he reported his business beneath Yue's head, sacrificed, and wept for him.", idiomatic: "Luan Bu, a great officer of Liang, had been envoy to Qi; on his return he reported his business beneath Peng Yue's head, sacrificed, and wept for him." },
  { zh: "吏捕以聞。", literal: "Officers arrested him and reported.", idiomatic: "Officers arrested him and reported it." },
  { zh: "上召布，罵，欲烹之。", literal: "The sovereign summoned Bu, reviled him, and wished to boil him.", idiomatic: "The Emperor summoned Bu, reviled him, and wished to boil him alive." },
  { zh: "方提趨湯，布顧曰：「願一言而死。", literal: "Just as they were dragging him toward the cauldron, Bu looked back, saying: \"I wish one word before I die.", idiomatic: "Just as they were dragging him toward the cauldron, Bu looked back and said: \"Let me speak one word before I die." },
  { zh: "」上曰：「何言？", literal: "\" The sovereign said: \"What word?\"", idiomatic: "\" The Emperor said: \"What word?\"" },
  { zh: "」布曰：「方上之困於彭城，敗滎陽、成皋間，項王所以遂不能西者，徒以彭王居梁地，與漢合從苦楚也。", literal: "\" Bu said: \"When Your Majesty was cornered at Pengcheng and defeated between Xingyang and Chenggao, the reason the King of Xiang in the end could not advance west was solely that the King of Peng held Liang territory and united with Han to harass Chu from the east.", idiomatic: "\" Bu said: \"When Your Majesty was cornered at Pengcheng and defeated between Xingyang and Chenggao, the reason the King of Xiang could not advance west was solely that King Peng held Liang and united with Han to harass Chu from the east." },
  { zh: "當是之時，王一顧，與楚則漢破，與漢則楚破。", literal: "At that time, one turn of the king's head—if with Chu, Han was broken; if with Han, Chu was broken.", idiomatic: "At that time one turn of his head—if with Chu, Han was broken; if with Han, Chu was broken." },
  { zh: "且垓下之會，微彭王，項氏不亡。", literal: "And at the meeting at Gaixia, but for the King of Peng, the house of Xiang would not have perished.", idiomatic: "And at Gaixia, but for King Peng, the house of Xiang would not have perished." },
  { zh: "天下已定，彭王剖符受封，亦欲傳之萬世。", literal: "All under Heaven was settled; the King of Peng split tally and received enfeoffment, and also wished to pass it on for ten thousand generations.", idiomatic: "The realm was settled; King Peng split tally and received enfeoffment and also wished to pass his realm on for ten thousand generations." },
  { zh: "今陛下一徵兵於梁，彭王病不行。", literal: "Now Your Majesty one summons for troops from Liang, and the King of Peng, ill, did not go.", idiomatic: "Now Your Majesty summoned troops from Liang once, and King Peng, ill, did not go." },
  { zh: "而陛下疑以為反；", literal: "yet Your Majesty suspected him as rebel;", idiomatic: "yet Your Majesty suspected him of rebellion;" },
  { zh: "反形未具，以苛小案誅滅之。", literal: "before marks of rebellion were complete, on a harsh petty charge you executed and extinguished him.", idiomatic: "before the marks of rebellion were complete, on a harsh petty charge you executed and extinguished him." },
  { zh: "臣恐功臣人人自危也。", literal: "Your servant fears that merit-holders will each feel peril in himself.", idiomatic: "I fear that every meritorious minister will feel peril in himself." },
  { zh: "今彭王已死，臣生不如死，請就烹。", literal: "Now the King of Peng is dead; your servant's living is not as good as death—I request to go to the cauldron.\"", idiomatic: "Now King Peng is dead; living is worse than death for me—I ask to go to the cauldron.\"" },
  { zh: "」於是上乃釋布罪，拜為都尉。", literal: "\" Thereupon the sovereign released Bu's guilt and appointed him Commandant.", idiomatic: "\" Thereupon the Emperor released Bu and appointed him Commandant." },
  { zh: "----7丙午，立皇子恢為梁王。", literal: "----7 On bingwu, he established the Prince Hui as King of Liang.", idiomatic: "----7 On bingwu, he made Prince Hui King of Liang." },
  { zh: "丙寅，立皇子友為淮陽王。", literal: "On bingyin, he established the Prince You as King of Huaiyang.", idiomatic: "On bingyin, he made Prince You King of Huaiyang." },
  { zh: "罷東郡，頗益梁；", literal: "He abolished the Dong commandery and largely added to Liang;", idiomatic: "He abolished Dong commandery and largely added its territory to Liang;" },
  { zh: "罷穎川郡，頗益淮陽。", literal: "abolished the Yingchuan commandery and largely added to Huaiyang.", idiomatic: "abolished Yingchuan commandery and largely added its territory to Huaiyang." },
  { zh: "----8夏，四月，行自洛陽至。", literal: "----8 In summer, the fourth month, the emperor's procession returned from Luoyang.", idiomatic: "----8 In summer, the fourth month, the imperial procession returned from Luoyang." },
  { zh: "----9五月，詔立秦南海尉趙佗為南粵王，使陸賈即授璽綬，與剖符通使，使和集百越，無為南邊患害。", literal: "----9 In the fifth month, an edict established Zhao Tuo, the Commandant of Nanhai under Qin, as King of Nanyue, sent Lu Jia to invest him with seal and ribbon at once, split tally for mutual envoys, and cause the hundred Yue to be harmonized and gathered, doing no harm as southern-border trouble.", idiomatic: "----9 In the fifth month, an edict made Zhao Tuo, Qin's Commandant of Nanhai, King of Nanyue, sent Lu Jia to invest him with seal and ribbon at once, split tally for mutual envoys, and harmonize the hundred Yue so they would not trouble the southern border." },
  { zh: "初，秦二世時，南海尉任囂病且死。", literal: "At first, in the time of Qin Er Shi, the Commandant of Nanhai, Ren Xiao, was ill and near death.", idiomatic: "Earlier, in the reign of Qin Er Shi, Commandant of Nanhai Ren Xiao was ill and near death." },
  { zh: "召龍川令趙佗，語曰：「秦為無道，天下苦之。", literal: "He summoned the magistrate of Longchuan, Zhao Tuo, and said: \"Qin is without the Way; all under Heaven suffer from it.", idiomatic: "He summoned Longchuan magistrate Zhao Tuo and said: \"Qin is without the Way; all under Heaven suffer from it." },
  { zh: "聞陳勝等作亂，天下未知所安。", literal: "Hearing Chen Sheng and others have risen in disorder, all under Heaven does not know where it will settle.", idiomatic: "Hearing that Chen Sheng and others have risen in disorder, the realm does not know where it will settle." },
  { zh: "南海僻遠，吾恐盜兵侵地至此，欲興兵絕新道自備，待諸侯變；", literal: "Nanhai is remote and distant; I fear that bandit troops may invade the land as far as here; I wish to raise troops and cut the new road to defend ourselves, waiting for changes among the feudal lords;", idiomatic: "Nanhai is remote; I fear bandit troops may invade as far as here; I wish to raise troops, cut the new road, and defend ourselves, waiting for changes among the feudal lords;" },
  { zh: "會病甚。", literal: "but I meet with grave illness.", idiomatic: "but I am gravely ill." },
  { zh: "且番禺負山險，阻南海，東西數千里，頗有中國人相輔；", literal: "Moreover Panyu backs on mountainous defile and blocks the South Sea; east and west several thousand li—with many men of the Central States to assist;", idiomatic: "Moreover Panyu backs on mountain defiles and blocks the South Sea; east and west it spans several thousand li, with many men of the Central States to assist;" },
  { zh: "此亦一州之主也，可以立國。", literal: "this too is master of a whole province; one may establish a state.", idiomatic: "this too can sustain a whole province; one may establish a state here." },
  { zh: "郡中長吏，無足與言者，故召公告之。", literal: "Among the long-term officials of the commandery there is no one fit to speak with; therefore I summoned you, sir, to tell you.\"", idiomatic: "Among the commandery's senior officials there is no one fit to speak with; therefore I summoned you, sir, to tell you.\"" },
  { zh: "」即被佗書，行南海尉事。", literal: "\" Thereupon he invested Tuo with the writ and charged him with the affairs of Nanhai Commandant.", idiomatic: "\" Thereupon he invested Tuo with the writ and charged him with the affairs of Commandant of Nanhai." },
  { zh: "囂死，佗即移檄告橫浦、陽山、湟谿關曰：「盜兵且至，急絕道，聚兵自守！", literal: "Xiao died; Tuo at once issued a proclamation to the passes of Hengpu, Yangshan, and Huangxi, saying: \"Bandit troops are about to arrive—hasten to cut the roads, gather troops, and defend yourselves!", idiomatic: "Xiao died; Tuo at once issued a proclamation to the passes of Hengpu, Yangshan, and Huangxi: \"Bandit troops are about to arrive—hasten to cut the roads, gather troops, and defend yourselves!" },
  { zh: "」因稍以法誅秦所置長吏，以其黨為假守。", literal: "\" Then gradually by law he executed the long-term officials Qin had placed, making his faction acting administrators.", idiomatic: "\" Then gradually, by law, he executed the senior officials Qin had placed and made his own followers acting administrators." },
  { zh: "秦已破滅，佗即擊並桂林、象郡，自立為南越武王。", literal: "Qin was already broken and extinguished; Tuo at once attacked and annexed Guilin and Xiang commanderies and established himself as Martial King of Nanyue.", idiomatic: "After Qin was broken and extinguished, Tuo attacked and annexed Guilin and Xiang commanderies and made himself Martial King of Nanyue." },
  { zh: "陸生至，尉佗魋結、箕倨見陸生。", literal: "Master Lu arrived; Wei Tuo wore his hair in a chignon and sat with legs spread insolently to receive Master Lu.", idiomatic: "When Master Lu arrived, Zhao Tuo wore his hair in a chignon and received him sitting with legs spread insolently." },
  { zh: "陸生說佗曰：「足下中國人，親戚、昆弟墳墓在真定。", literal: "Master Lu urged Tuo: \"Your feet are a man of the Central States; your kinsmen and the graves of brothers are at Zhending.", idiomatic: "Master Lu urged him: \"You are a man of the Central States; your kinsmen and your brothers' graves are at Zhending." },
  { zh: "今足下反天性，棄冠帶，欲以區區之越與天子抗衡為敵國，禍且及身矣。", literal: "Now your feet turn against Heaven-nature, cast off cap and sash, and wish with the mere Yue to oppose the Son of Heaven as enemy state—disaster will reach your person.", idiomatic: "Now you turn against your nature, cast off cap and sash, and wish with mere Yue to oppose the Son of Heaven as an enemy state—disaster will reach you." },
  { zh: "且夫秦失其政，諸族、豪桀並起，唯漢王先入關，據咸陽。", literal: "Moreover Qin lost its government; all clans and powerful heroes rose together, yet only the King of Han entered the passes first and held Xianyang.", idiomatic: "Moreover Qin lost its government; clans and powerful heroes rose everywhere, yet only the King of Han entered the passes first and held Xianyang." },
  { zh: "項羽倍約，自立為西楚霸王，諸侯皆屬，可謂至強。", literal: "Xiang Yu broke faith, made himself Western Chu Overlord, and all feudal lords submitted—one may say supremely strong.", idiomatic: "Xiang Yu broke faith, made himself Western Chu Overlord, and all feudal lords submitted—he was supremely strong." },
  { zh: "然漢王起巴、蜀，鞭笞天下，遂誅項羽，滅之。", literal: "Yet the King of Han rose from Ba and Shu, whipped all under Heaven, and in the end executed Xiang Yu and extinguished him.", idiomatic: "Yet the King of Han rose from Ba and Shu, whipped the realm, and in the end executed Xiang Yu and destroyed him." },
  { zh: "五年之間，海內平定。", literal: "Within five years the realm within the seas was pacified.", idiomatic: "Within five years the realm was pacified." },
  { zh: "此非人力，天之所建也。", literal: "This is not human strength—it is what Heaven has established.", idiomatic: "This is not human strength—it is what Heaven has established." },
  { zh: "天子聞君王王南越，不助天下誅暴逆，將相欲移兵而誅王。", literal: "The Son of Heaven heard that you, king, ruled Southern Yue and did not aid all under Heaven in punishing violent rebels; ministers and generals wished to move troops to execute you.", idiomatic: "The Son of Heaven heard that you ruled Southern Yue and did not aid the realm in punishing violent rebels; ministers and generals wished to move troops to execute you." },
  { zh: "天子憐百姓新勞苦，故且休之，遣臣授君王印，剖符通使。", literal: "The Son of Heaven pitied the people newly wearied and toiled, so for the time rested them and sent your servant to invest you with the king's seal and split tally for mutual envoys.", idiomatic: "The Son of Heaven pitied the people, newly wearied and toiled, so for now he rested them and sent me to invest you with the king's seal and split tally for mutual envoys." },
  { zh: "君王宜郊迎，北面稱臣；", literal: "You, king, ought to meet him in the suburbs and face north as subject;", idiomatic: "Your Majesty ought to meet him in the suburbs and face north as subject;" },
  { zh: "乃欲以新造未集之越，屈強於此！", literal: "yet you wish with newly made, not yet gathered Yue to bend strength here!", idiomatic: "yet you wish with newly made, not yet gathered Yue to stand defiant here!" },
  { zh: "漢誠聞之，掘燒王先人塚，夷滅宗族，使一偏將將十萬眾臨越，則越殺王降漢如反覆手耳。", literal: "If Han truly heard of it, they would dig up and burn your king's forefathers' graves, extinguish clan and kindred, and send one wing general with a host of a hundred thousand to descend on Yue—then Yue would kill its king and surrender to Han like turning the hand.", idiomatic: "If Han truly heard of it, they would dig up and burn your forefathers' graves, extinguish your clan, and send one wing general with a host of a hundred thousand against Yue—then Yue would kill its king and surrender to Han like turning the hand." },
  { zh: "」於是尉佗乃蹶然起坐，謝陸生曰：「居蠻夷中久，殊失禮義。", literal: "\" Thereupon Wei Tuo suddenly started up and sat, apologizing to Master Lu: \"Dwelling long among barbarian Yi, I have utterly lost rites and propriety.", idiomatic: "\" Thereupon Zhao Tuo suddenly rose and sat, apologizing to Master Lu: \"Dwelling long among barbarians, I have utterly lost rites and propriety." },
  { zh: "」因問陸生曰：「我孰與蕭何、曹參、韓信賢？", literal: "\" Then he asked Master Lu: \"Compared with Xiao He, Cao Shen, and Han Xin—which am I the more worthy?\"", idiomatic: "\" Then he asked Master Lu: \"Compared with Xiao He, Cao Shen, and Han Xin—which of us is the worthier?\"" },
  { zh: "」陸生曰：「王似賢也。", literal: "\" Master Lu said: \"Your Majesty seems worthy.\"", idiomatic: "\" Master Lu said: \"Your Majesty seems worthy.\"" },
  { zh: "」復曰：「我孰與皇帝賢？", literal: "\" Again he said: \"Compared with the Emperor—which am I the more worthy?\"", idiomatic: "\" Again he asked: \"Compared with the Emperor—which of us is the worthier?\"" },
  { zh: "」陸生曰：「皇帝繼五帝、三皇之業，統理中國；", literal: "\" Master Lu said: \"The Emperor continues the enterprise of the Five Emperors and Three August Ones, governing and ordering the Central States;", idiomatic: "\" Master Lu said: \"The Emperor continues the enterprise of the Five Emperors and Three August Ones and governs the Central States;" },
  { zh: "中國之人以億計，地方萬里，萬物殷富；", literal: "the people of the Central States number in the hundreds of millions; territory ten thousand li; all things abundant and rich;", idiomatic: "its people number in the hundreds of millions; its territory spans ten thousand li; all things are abundant and rich;" },
  { zh: "政由一家，自天地剖判未始有也。", literal: "government from one house—from when Heaven and Earth were first split there has never been such.", idiomatic: "government from one house—from when Heaven and Earth were first split there has never been such." },
  { zh: "今王眾不過十萬，皆蠻夷，崎嶇山海間，譬若漢一郡耳，何乃比於漢？", literal: "Now your Majesty's masses are no more than a hundred thousand, all barbarian Yi in rugged mountains and seas—comparable to but one commandery of Han; how then compare with Han?\"", idiomatic: "Now Your Majesty's masses are no more than a hundred thousand, all barbarians in rugged mountains and seas—comparable to but one commandery of Han; how then compare with Han?\"" },
  { zh: "」尉佗大笑曰：「吾不起中國，故王此；", literal: "\" Wei Tuo laughed greatly: \"I did not rise in the Central States, therefore I am king here;", idiomatic: "\" Zhao Tuo laughed loudly: \"I did not rise in the Central States, therefore I am king here;" },
  { zh: "使我居中國，何遽不若漢？", literal: "had you placed me in the Central States, how would I suddenly fail to match Han?\"", idiomatic: "had you placed me in the Central States, how would I suddenly fail to match Han?\"" },
  { zh: "」乃留陸生與飲。", literal: "\" Thereupon he detained Master Lu to drink with him.", idiomatic: "\" Thereupon he detained Master Lu to drink with him." },
  { zh: "數月，曰：「越中無足與語。", literal: "After several months he said: \"Within Yue there is no one fit to speak with.", idiomatic: "After several months he said: \"Within Yue there is no one fit to speak with." },
  { zh: "至生來，令我日聞所不聞。", literal: "When the Gentleman came, he made me day by day hear what I had not heard.\"", idiomatic: "When the Gentleman came, he made me day by day hear what I had never heard.\"" },
  { zh: "」賜陸生橐中裝直千金，他送亦千金。", literal: "\" He bestowed on Master Lu goods in the sack worth a thousand in gold, and other gifts also a thousand in gold.", idiomatic: "\" He bestowed on Master Lu goods in his sack worth a thousand in gold, and other gifts also worth a thousand in gold." },
  { zh: "陸生卒拜尉佗為南越王，令稱臣，奉漢約。", literal: "Master Lu in the end enfeoffed Wei Tuo as King of Nanyue, ordering him to call himself subject and observe Han's covenant.", idiomatic: "Master Lu in the end enfeoffed Zhao Tuo as King of Nanyue, ordering him to call himself subject and observe Han's covenant." },
  { zh: "歸報，帝大悅，拜賈為太中大夫。", literal: "Returning to report, the Emperor was greatly pleased and appointed Jia Grand Master of the Palace.", idiomatic: "On his return he reported; the Emperor was greatly pleased and appointed Jia Grand Master of the Palace." },
  { zh: "陸生時時前說稱《詩》、《書》，帝罵之曰：「乃公居馬上而得之，安事《詩》、《書》？", literal: "Master Lu from time to time advanced and urged, praising the Odes and Documents; the Emperor reviled him: \"Your daddy got it on horseback—what business have the Odes and Documents?", idiomatic: "Master Lu from time to time advanced and praised the Odes and Documents; the Emperor reviled him: \"Your daddy got it on horseback—what business have the Odes and Documents?" },
  { zh: "」陸生曰：「居馬上得之，寧可以馬上治之乎？", literal: "\" Master Lu said: \"Got it on horseback—can you govern it on horseback?", idiomatic: "\" Master Lu said: \"You got it on horseback—can you govern it on horseback?" },
  { zh: "且湯、武逆取而以順守之；", literal: "Moreover Tang and Wu took it in reversal but guarded it in accordance;", idiomatic: "Moreover Tang and Wu took it by force but guarded it by compliance;" },
  { zh: "文武並用，長久之術也。", literal: "civil and martial employed together—that is the art of long endurance.", idiomatic: "civil and martial employed together—that is the art of long endurance." },
  { zh: "昔者吳王夫差、智伯、秦始皇，皆以極武而亡。", literal: "In the past King Fuchai of Wu, Earl Zhi, and the First Emperor of Qin all by extreme martialism perished.", idiomatic: "In the past King Fuchai of Wu, Earl Zhi, and the First Emperor of Qin all perished through extreme martialism." },
  { zh: "鄉使秦已並天下，行仁義，法先聖，陛下安得而有之？", literal: "If only Qin had already united all under Heaven and practiced benevolence and righteousness, taking the former sages as model, how would Your Majesty have obtained it?\"", idiomatic: "If Qin had already united the realm and practiced benevolence and righteousness, taking the former sages as model, how would Your Majesty have obtained it?\"" },
  { zh: "」帝有慚色，曰：「試為我著秦所以失天下、吾所以得之者及古成敗之國。", literal: "\" The Emperor had a look of shame and said: \"Try to write for me how Qin lost all under Heaven, how We obtained it, and states of antiquity whose success and failure...", idiomatic: "\" The Emperor looked ashamed and said: \"Try to write for me how Qin lost the realm, how I obtained it, and the success and failure of states in antiquity." },
  { zh: "」陸生乃粗述存亡之征，凡著十二篇。", literal: "\" Master Lu then roughly set forth the signs of survival and perdition, all together composing twelve chapters.", idiomatic: "\" Master Lu then roughly set forth the signs of survival and perdition, composing twelve chapters in all." },
  { zh: "每奏一篇，帝未嘗不稱善，左右呼萬歲；", literal: "Each time he presented a chapter, the Emperor never failed to praise it well, and those at his sides cried \"ten thousand years\";", idiomatic: "Each time he presented a chapter, the Emperor never failed to praise it, and those at his sides cried \"ten thousand years\";" },
  { zh: "號其書曰《新語》。", literal: "they styled his book New Discourses.", idiomatic: "they styled his book New Discourses." },
  { zh: "----10帝有疾，惡見人，臥禁中，詔戶者無得入群臣，群臣絳、灌等莫敢入，十餘日。", literal: "----10 The Emperor was ill, loathed seeing people, lay within the forbidden apartments, and edicted that doorkeepers were not to admit the ministers; the ministers Zhou Bo, Guan Ying, and others dared not enter—for more than ten days.", idiomatic: "----10 The Emperor fell ill, loathed seeing anyone, and lay in the inner palace; he ordered doorkeepers not to admit ministers, and for more than ten days Zhou Bo, Guan Ying, and the rest dared not enter." },
  { zh: "舞陽侯樊噲排闥直入，大臣隨之。", literal: "Marquis of Wuyang, Fan Kuai, pushed open the side door and entered straight in; the great ministers followed.", idiomatic: "Marquis of Wuyang Fan Kuai pushed through the side door and went straight in, and the great ministers followed." },
  { zh: "上獨枕一宦者臥。", literal: "The Emperor lay alone with his head on one eunuch's lap.", idiomatic: "The Emperor lay alone with his head pillowed on a eunuch." },
  { zh: "噲等見上，流涕曰：「始陛下與臣等起豐、沛，定天下，何其壯也？", literal: "Fan Kuai and the others, seeing the Emperor, wept and said, “At first Your Majesty rose with us from Feng and Pei and settled the realm—how stalwart that was!", idiomatic: "When Fan Kuai and the others saw him they wept and said, “When Your Majesty rose with us from Feng and Pei and settled the realm, how stalwart you were!" },
  { zh: "今天下已定，又何憊也？", literal: "Now the realm is settled—why so weary?", idiomatic: "Now the realm is settled—why so weary?" },
  { zh: "且陛下病甚，大臣震恐；", literal: "Moreover Your Majesty is gravely ill and the great ministers are shaken with fear;", idiomatic: "Your Majesty is gravely ill and the ministers are terrified;" },
  { zh: "不見臣等計事，顧獨與一宦者絕乎？", literal: "you will not see us to plan affairs, yet would cut yourself off alone with one eunuch?", idiomatic: "you will not see us to plan affairs, yet shut yourself off with a single eunuch?" },
  { zh: "且陛下獨不見趙高之事乎？", literal: "Has Your Majesty alone not seen what happened with Zhao Gao?", idiomatic: "Has Your Majesty forgotten what happened with Zhao Gao?" },
  { zh: "」帝笑而起。", literal: "” The Emperor laughed and rose.", idiomatic: "” The Emperor laughed and got up." },
  { zh: "----11秋，七月，淮南王布反。", literal: "----11 In autumn, the seventh month, the King of Huainan, Bu, rebelled.", idiomatic: "----11 In autumn, the seventh month, King Bu of Huainan rebelled." },
  { zh: "初，淮陰侯死，布已心恐。", literal: "At first, when the Marquis of Huaiyin died, Bu was already fearful at heart.", idiomatic: "Earlier, when the Marquis of Huaiyin was executed, Bu was already afraid." },
  { zh: "及彭越誅，醢其肉以賜諸侯。", literal: "When Peng Yue was executed, his flesh was made into paste and bestowed on the feudal lords.", idiomatic: "When Peng Yue was executed, his flesh was minced into paste and sent to the feudal lords." },
  { zh: "使者至淮南，淮南王方獵，見醢，因大恐，陰令人部聚兵，候伺旁郡警急。", literal: "When the envoy reached Huainan, the King of Huainan was just hunting; seeing the paste, he was greatly afraid and secretly ordered men to muster troops and watch neighboring commanderies for alarms.", idiomatic: "When the envoy reached Huainan the king was hunting; seeing the paste he was terrified and secretly ordered troops gathered and watches set on neighboring commanderies." },
  { zh: "布所幸姬病就醫，醫家與中大夫賁赫對門，赫乃厚饋遺，從姬飲醫家；", literal: "A favorite concubine of Bu fell ill and went to a physician; the physician's house faced that of the palace grandee Ben He, who therefore sent rich gifts and drank with the concubine at the physician's house;", idiomatic: "A favorite concubine of Bu fell ill and sought a physician; the physician lived opposite Palace Grandee Ben He, who sent lavish gifts and drank with the concubine at the physician's house;" },
  { zh: "王疑其與亂，欲捕赫。", literal: "the king suspected him of plotting disorder and wished to seize He.", idiomatic: "the king suspected him of plotting rebellion and meant to arrest He." },
  { zh: "赫乘傳詣長安上變，言：「布謀反有端，可先未發誅也。", literal: "He took post-horses and went to Chang'an to report a crisis, saying, “Bu's plotting rebellion has clear signs; he may be executed before he rises.", idiomatic: "He took relay horses to Chang'an and reported: “Bu's rebellion has clear signs; he can be executed before he rises." },
  { zh: "」上讀其書，語蕭相國，相國曰：「布不宜有此，恐仇怨妄誣之。", literal: "” The Emperor read his memorial and spoke with Chancellor Xiao; the chancellor said, “Bu ought not to have this; I fear a personal enemy falsely accused him.", idiomatic: "” The Emperor read his report and consulted Chancellor Xiao, who said, “Bu is unlikely to do this; I fear an enemy falsely accused him." },
  { zh: "請系赫，使人微驗淮南王。", literal: "I ask that He be detained and men be sent to investigate the King of Huainan quietly.", idiomatic: "Detain He and send men to investigate the King of Huainan discreetly." },
  { zh: "」淮南王布見赫以罪亡上變，固已疑其言國陰事；", literal: "” The King of Huainan, Bu, seeing that He had fled after a crime to report a crisis, already suspected that he had disclosed the state's secrets;", idiomatic: "” King Bu of Huainan, seeing He flee after a crime to report him, already suspected He had revealed state secrets;" },
  { zh: "漢使又來，頗有所驗；", literal: "Han envoys came again and found much to verify;", idiomatic: "Han envoys came again and found much confirmed;" },
  { zh: "遂族赫家，發兵反。", literal: "thereupon he destroyed He's clan by degrees and raised troops in rebellion.", idiomatic: "so he wiped out He's clan and rose in arms." },
  { zh: "反書聞，上乃赦賁赫，以為將軍。", literal: "When word of the rebellion arrived, the Emperor then pardoned Ben He and made him a general.", idiomatic: "When news of the rebellion arrived, the Emperor pardoned Ben He and made him a general." },
  { zh: "上召諸將問計，皆曰：「發兵擊之，坑豎子耳，何能為乎？", literal: "The Emperor summoned the generals to ask their plans; all said, “Send troops to strike him—bury the brat, that's all; what can he do?", idiomatic: "The Emperor summoned the generals for counsel; all said, “Send troops and crush him—he's just a brat; what can he do?" },
  { zh: "」汝陰侯滕公召故楚令尹薛公問之。", literal: "” Marquis of Ruyin, the Lord of Teng, summoned the former Chu prime minister, the Lord of Xue, and questioned him.", idiomatic: "” Marquis of Ruyin the Lord of Teng summoned the former Chu prime minister, the Lord of Xue, and asked him." },
  { zh: "令尹曰：「是固當反。", literal: "The prime minister said, “He was bound to rebel.", idiomatic: "The prime minister said, “He was bound to rebel." },
  { zh: "」滕公曰：「上裂地而封之，疏爵而王之；", literal: "” The Lord of Teng said, “Your Majesty split lands and enfeoffed him, raised him in noble rank and made him a king;", idiomatic: "” The Lord of Teng said, “Your Majesty carved out lands and enfeoffed him, raised his rank and made him a king;" },
  { zh: "其反何也？", literal: "why would he rebel?", idiomatic: "why would he rebel?" },
  { zh: "」令尹曰：「往年殺彭越，前年殺韓信；", literal: "” The prime minister said, “Last year Peng Yue was killed; the year before, Han Xin was killed;", idiomatic: "” The prime minister said, “Last year Peng Yue was killed; the year before, Han Xin;" },
  { zh: "此三人者，同功一體之人也，自疑禍及身，故反耳。", literal: "these three were men of the same merit and one body; suspecting that disaster would reach themselves, they rebelled.", idiomatic: "these three were men of equal merit and one mold; fearing disaster would reach them, they rebelled." },
  { zh: "」滕公言之上，上乃召見，問薛公，薛公對曰：「布反不足怪也。", literal: "” The Lord of Teng reported this to the Emperor; the Emperor then summoned him and questioned the Lord of Xue, who replied, “Bu's rebellion is not strange.", idiomatic: "” The Lord of Teng told the Emperor, who summoned the Lord of Xue and asked him; he replied, “Bu's rebellion is no surprise." },
  { zh: "使布出於上計，山東非漢之有也；", literal: "If Bu adopts the upper plan, the lands east of the mountains will not belong to Han;", idiomatic: "If Bu adopts the upper plan, the east will no longer belong to Han;" },
  { zh: "出於中計，勝敗之數未可知也；", literal: "if he adopts the middle plan, whether he wins or loses cannot yet be known;", idiomatic: "if the middle plan, victory and defeat are uncertain;" },
  { zh: "出於下計，陛下安枕而臥矣。", literal: "if he adopts the lower plan, Your Majesty may rest your head on the pillow and sleep.", idiomatic: "if the lower plan, Your Majesty may sleep in peace." },
  { zh: "」上曰：「何謂上計？", literal: "” The Emperor said, “What is called the upper plan?", idiomatic: "” The Emperor said, “What is the upper plan?" },
  { zh: "」對曰：「東取吳，西取楚，並齊，取魯，傳檄燕、趙，固守其所，山東非漢之有也。", literal: "” He replied, “Take Wu in the east and Chu in the west, absorb Qi, seize Lu, send proclamations to Yan and Zhao, and hold fast to what he has—the lands east of the mountains will not belong to Han.", idiomatic: "” He replied, “Take Wu in the east and Chu in the west, absorb Qi, seize Lu, send proclamations to Yan and Zhao, and hold his ground—the east will no longer belong to Han." },
  { zh: "」「何謂中計？", literal: "”“What is called the middle plan?", idiomatic: "”“What is the middle plan?" },
  { zh: "」「東取吳，西取楚，並韓，取魏，據敖倉之粟，塞成皋之口，勝敗之數未可行也。", literal: "”“Take Wu in the east and Chu in the west, absorb Han, seize Wei, hold the grain of the Ao granary, block the mouth of Chenggao—the count of victory and defeat cannot yet be settled.", idiomatic: "”“Take Wu in the east and Chu in the west, absorb Han, seize Wei, hold the Ao granary's grain, block Chenggao—the outcome cannot yet be told." },
  { zh: "」「何謂下計？", literal: "”“What is called the lower plan?", idiomatic: "”“What is the lower plan?" },
  { zh: "」「東取吳，西取下蔡，歸重於越，身歸長沙，陛下安枕而臥，漢無事矣。", literal: "”“Take Wu in the east and Xiapi in the west, shift his weight to Yue, return in person to Changsha—Your Majesty may rest your head on the pillow and sleep, and Han will have no trouble.", idiomatic: "”“Take Wu in the east and Xiapi in the west, shift his weight to Yue, return in person to Changsha—Your Majesty may sleep in peace and Han will be untroubled." },
  { zh: "」上曰：「是計將安出？", literal: "” The Emperor said, “Which plan will he adopt?", idiomatic: "” The Emperor said, “Which plan will he choose?" },
  { zh: "」對曰：「出下計。", literal: "” He replied, “He will adopt the lower plan.", idiomatic: "” He replied, “The lower plan." },
  { zh: "」上曰：「何謂廢上、中計而出下計？", literal: "” The Emperor said, “Why do you discard the upper and middle plans and choose the lower?", idiomatic: "” The Emperor said, “Why abandon the upper and middle plans for the lower?" },
  { zh: "」對曰：「布，故麗山之徒也，自致萬乘之主，此皆為身，不顧後、為百姓萬世慮者也。", literal: "” He replied, “Bu was formerly a captive at Mount Li; he raised himself to lord of ten thousand chariots—these are men who act for themselves, who do not look to what follows or plan for the people for ten thousand generations.", idiomatic: "” He replied, “Bu was once a captive at Mount Li and made himself lord of ten thousand chariots—such men act for themselves, heedless of consequences and of the people for generations to come." },
  { zh: "故曰出下計。", literal: "Therefore I say he will adopt the lower plan.", idiomatic: "So I say he will take the lower plan." },
  { zh: "」上曰：「善！", literal: "” The Emperor said, “Good!", idiomatic: "” The Emperor said, “Good!" },
  { zh: "」封薛公千戶。", literal: "” He enfeoffed the Lord of Xue with a fief of one thousand households.", idiomatic: "” He enfeoffed the Lord of Xue with one thousand households." },
  { zh: "乃立皇子長為淮南王。", literal: "He then established the imperial son Chang as King of Huainan.", idiomatic: "He then made his son Chang King of Huainan." },
  { zh: "是時，上有疾，欲使太子往擊黥布。", literal: "At that time the Emperor was ill and wished to send the crown prince to attack Qing Bu.", idiomatic: "At that time the Emperor was ill and meant to send the crown prince against Qing Bu." },
  { zh: "太子客東園公、綺里季、夏黃公、角里先生說建成侯呂釋之曰：「太子將兵，有功則位不益，無功則從此受禍矣。", literal: "The crown prince's retainers Dongyuan Gong, Qili Ji, Xia Huang Gong, and Master Jueli persuaded Marquis of Jian'cheng Lü Shizhi, saying, “If the crown prince commands troops, with merit his rank will not increase, and without merit from this he will suffer disaster.", idiomatic: "The crown prince's retainers Dongyuan Gong, Qili Ji, Xia Huang Gong, and Master Jueli urged Marquis of Jian'cheng Lü Shizhi: “If the crown prince commands troops, success will not raise his standing, and failure will bring disaster." },
  { zh: "君何不急請呂后，承間為上泣言：『黥布，天下猛將也，善用兵。", literal: "Why do you not urgently ask Empress Lü, seize an occasion to weep before the Emperor, and say, ‘Qing Bu is the realm's fierce general and skilled in using troops.", idiomatic: "Urge Empress Lü at once to seize a moment and weep before the Emperor: ‘Qing Bu is the realm's fiercest general and a master of war." },
  { zh: "今諸將皆陛下故等夷，乃令太子將此屬，無異使羊將狼，莫肯為用；", literal: "Now the generals are all Your Majesty's old equals, yet you would have the crown prince command these men—it is no different from making a sheep lead wolves; none will be willing to serve;", idiomatic: "The generals are all Your Majesty's old equals, yet you would put the crown prince over them—it is like setting a sheep to lead wolves; none will obey;" },
  { zh: "且使布聞之，則鼓行而西耳！", literal: "moreover, if Bu hears of it, he will beat his drums and march west!", idiomatic: "and if Bu hears of it he will beat his drums and march west at once!" },
  { zh: "上雖病，強載輜車，臥而護之，諸將不敢不盡力。", literal: "Though Your Majesty is ill, force yourself into the supply wagon, lie down and lead them—the generals will not dare fail to exert themselves.", idiomatic: "Though Your Majesty is ill, force yourself into the supply wagon and lead them lying down—the generals will not dare hold back." },
  { zh: "上雖苦，為妻子自強！", literal: "Though Your Majesty suffers, strive for your wife and son!", idiomatic: "Though it pains you, strive on for your wife and son!" },
  { zh: "』」於是呂釋之立夜見呂后。", literal: "’” Thereupon Lü Shizhi at once that night saw Empress Lü.", idiomatic: "’” Thereupon Lü Shizhi went to Empress Lü that very night." },
  { zh: "呂后承間為上泣涕而言，如四人意。", literal: "Empress Lü seized an occasion to weep before the Emperor and speak as the four men had wished.", idiomatic: "Empress Lü seized a moment, wept before the Emperor, and spoke as the four had urged." },
  { zh: "上曰：「吾惟豎子固不足遣，而公自行耳。", literal: "The Emperor said, “I knew the brat was truly not fit to send; I myself will go.", idiomatic: "The Emperor said, “I knew the boy was not fit to send; I will go myself." },
  { zh: "於是上自將兵而東，群臣居守，皆送至霸上。", literal: "Thereupon the Emperor personally led troops east; the ministers remained to guard and all escorted him to Bashang.", idiomatic: "The Emperor then led the army east in person; the ministers stayed behind and escorted him to Bashang." },
  { zh: "留侯病，自強起，至曲郵，見上曰：「臣宜從，病甚。", literal: "The Marquis of Liu was ill but forced himself up; reaching Qu'e, he saw the Emperor and said, “I ought to follow, but my illness is severe.", idiomatic: "The Marquis of Liu was ill but forced himself up; at Qu'e he saw the Emperor and said, “I ought to follow, but I am too ill." },
  { zh: "楚人剽疾，願上無與爭鋒！", literal: "The men of Chu are swift and fierce; I wish Your Majesty would not contend with them at the spearpoint!", idiomatic: "The men of Chu are swift and fierce; do not meet them head-on!" },
  { zh: "」因說上令太子為將軍，監關中兵。", literal: "” He therefore urged the Emperor to make the crown prince general and supervise the Guanzhong troops.", idiomatic: "” He urged the Emperor to make the crown prince general and supervise the Guanzhong forces." },
  { zh: "上曰：「子房雖病，強臥而傅太子。", literal: "The Emperor said, “Though Zifang is ill, force yourself to lie down and tutor the crown prince.", idiomatic: "The Emperor said, “Though Zifang is ill, force yourself to tutor the crown prince from your bed." },
  { zh: "」是時，叔孫通為太傅，留侯行少傅事。", literal: "” At that time Shusun Tong was grand tutor and the Marquis of Liu performed the duties of junior tutor.", idiomatic: "” Shusun Tong was grand tutor and the Marquis of Liu acted as junior tutor." },
  { zh: "發上郡、北地、隴西車騎、巴蜀材官及中尉卒三萬人為皇太子衛，軍霸上。", literal: "He mobilized chariots and horsemen from Shang commandery, Beidi, and Longxi, elite troops from Ba and Shu, and thirty thousand men of the commandant of the capital to guard the crown prince, encamped at Bashang.", idiomatic: "He mobilized chariots and cavalry from Shang, Beidi, and Longxi, elite troops from Ba and Shu, and thirty thousand capital guardsmen for the crown prince and encamped them at Bashang." },
  { zh: "布之初反，謂其將曰：「上老矣，厭兵，必不能來。", literal: "When Bu first rebelled he told his generals, “The Emperor is old and weary of war; he surely cannot come.", idiomatic: "When Bu first rebelled he told his generals, “The Emperor is old and sick of war; he will not come." },
  { zh: "使諸將，諸將獨患淮陰、彭越，今皆已死，餘不足畏也。", literal: "If he sends the generals, the generals feared only Huaiyin and Peng Yue; now both are dead—the rest are not worth fearing.", idiomatic: "If he sends his generals, they feared only Huaiyin and Peng Yue, and both are dead—the rest are nothing to fear." },
  { zh: "」故遂反。", literal: "” Therefore he rebelled.", idiomatic: "” So he rebelled." },
  { zh: "果如薛公之言，東擊荊。", literal: "It turned out as the Lord of Xue had said: he struck Jing in the east.", idiomatic: "It turned out as the Lord of Xue had said: he attacked Jing in the east." },
  { zh: "荊王賈走死富陵；", literal: "The King of Jing, Jia, fled and died at Fuling;", idiomatic: "King Jia of Jing fled and died at Fuling;" },
  { zh: "盡劫其兵，渡淮擊楚。", literal: "he seized all his troops, crossed the Huai, and attacked Chu.", idiomatic: "seized all his troops, crossed the Huai, and attacked Chu." },
  { zh: "楚發兵與戰徐、僮間。", literal: "Chu sent troops and fought him between Xu and Tong.", idiomatic: "Chu sent troops and fought him between Xu and Tong." },
  { zh: "為三軍，欲以相救為奇。", literal: "Chu divided into three armies, wishing to use mutual rescue as a stratagem.", idiomatic: "Chu split into three armies, hoping mutual rescue would be their advantage." },
  { zh: "或說楚將曰：「布善用兵，民素畏之。", literal: "Someone urged the Chu general, saying, “Bu is skilled in using troops and the people have long feared him.", idiomatic: "Someone urged the Chu commander: “Bu is skilled in war and the people have long feared him." },
  { zh: "且兵法：『諸侯自戰其地為散地』，今別為三，彼敗吾一軍，餘皆走，安能相救！", literal: "Moreover the art of war says, ‘When feudal lords fight on their own ground it is scattered ground’; now you are split in three—if he defeats one of our armies the rest will all flee; how can they rescue one another!", idiomatic: "Moreover the art of war says, ‘When lords fight on their own soil it is scattered ground’; split three ways, if he routs one army the rest will flee—how can they rescue each other!" },
  { zh: "」不聽。", literal: "” He would not listen.", idiomatic: "” He would not listen." },
  { zh: "布果破其一軍，其二軍散走；", literal: "Bu indeed broke one army; the other two armies scattered and fled;", idiomatic: "Bu routed one army as predicted; the other two scattered;" },
  { zh: "布遂引兵而西。", literal: "Bu then led his troops west.", idiomatic: "Bu then marched west." },
  { zh: "1冬，十月，上與布兵遇於蘄西，布兵精甚。", literal: "1 In winter, the tenth month, the Emperor met Bu's troops at Qixi; Bu's soldiers were very keen.", idiomatic: "1 In winter, the tenth month, the Emperor met Bu at Qixi; Bu's troops were very sharp." },
  { zh: "上壁庸城，望布軍置陳如項籍軍，上惡之。", literal: "The Emperor fortified Yongcheng; gazing at Bu's army he saw their array set out like Xiang Yu's army, and he hated it.", idiomatic: "The Emperor fortified Yongcheng; seeing Bu's array laid out like Xiang Yu's, he was repelled." },
  { zh: "與布相望見，遙謂布曰：「何苦而反？", literal: "Facing Bu at a distance he called to him, “Why toil to rebel?", idiomatic: "Facing Bu across the field he called, “Why rebel at such cost?" },
  { zh: "」布曰：「欲為帝耳！", literal: "” Bu said, “I wish to be emperor, that's all!", idiomatic: "” Bu said, “I want to be emperor, that's all!" },
  { zh: "」上怒罵之，遂大戰。", literal: "” The Emperor cursed him in anger and they joined in great battle.", idiomatic: "” The Emperor cursed him and they joined battle." },
  { zh: "布軍敗走，渡淮，數止戰，不利，與百餘人走江南，上令別將追之。", literal: "Bu's army was defeated and fled; crossing the Huai he several times halted to fight but fared ill, and with a little more than a hundred men fled into the lands south of the Yangtze; the Emperor ordered a separate general to pursue.", idiomatic: "Bu's army broke and fled; crossing the Huai he fought again and again without success, and fled south of the Yangtze with a little over a hundred men while the Emperor sent other generals in pursuit." },
  { zh: "----2上還，過沛，留，置酒沛宮，悉召故人、父老、諸母、子弟佐酒，道舊故為笑樂。", literal: "----2 The Emperor returned, passed through Pei, stayed, set out wine at the Pei palace, summoned all old friends, village elders, the neighborhood mothers, and younger kin to share the wine, and spoke of old times in laughter and joy.", idiomatic: "----2 On his return he passed through Pei, stayed, and held a feast at the Pei palace, calling all old friends, elders, neighborhood mothers, and younger kin to drink with him and reliving old times in laughter." },
  { zh: "酒酣，上自為歌，起舞，慷慨傷懷，泣數行下，謂沛父兄曰：「遊子悲故鄉。", literal: "When the wine was deep the Emperor himself composed a song, danced, was moved with generous grief, wept several lines down his face, and told the fathers and elders of Pei, “The wanderer grieves for his homeland.", idiomatic: "Deep in wine the Emperor sang, danced, was moved to generous grief, wept freely, and told the elders of Pei, “The wanderer grieves for home." },
  { zh: "朕自沛公以誅暴逆，遂有天下；", literal: "I from Duke of Pei punished the violent and rebellious and thereby gained the realm;", idiomatic: "I rose as Duke of Pei to punish the violent and rebellious and thereby gained the realm;" },
  { zh: "其以沛為朕湯沐邑，復其民，世世無有所與。", literal: "let Pei be my bath-and-rest fief, exempt its people, and for generation after generation grant them nothing more.", idiomatic: "let Pei be my personal fief, exempt its people, and never levy anything on them for all generations." },
  { zh: "」樂飲十餘日，乃去。", literal: "” They drank in joy for more than ten days before he departed.", idiomatic: "” They feasted for more than ten days before he left." },
  { zh: "----3漢別將擊英布軍洮水南、北，皆大破之。", literal: "----3 Han's separate generals struck Ying Bu's army south and north of the Tao River and routed them greatly.", idiomatic: "----3 Han's separate generals attacked Ying Bu south and north of the Tao River and routed him utterly." },
  { zh: "布故與番君婚，以故長沙成王臣使人誘布，偽欲與亡走越，布信而隨之。", literal: "Bu had formerly been allied by marriage with the Lord of Pan; for this reason King Cheng of Changsha, Chen, sent men to entice Bu, falsely wishing to flee with him to Yue; Bu believed them and followed.", idiomatic: "Bu had once been allied by marriage to the Lord of Pan; King Cheng of Changsha, Chen, sent men to lure him, pretending they would flee together to Yue; Bu believed them and followed." },
  { zh: "番陽人殺布茲鄉民田舍。", literal: "Men of Poyang killed Bu in a village field hut at Zixiang.", idiomatic: "Men of Poyang killed Bu in a village hut at Zixiang." },
  { zh: "----4周勃悉定代郡、雁門、雲中地，斬陳豨於當城。", literal: "----4 Zhou Bo fully settled the lands of Dai commandery, Yanmen, and Yunzhong and beheaded Chen Xi at Dangcheng.", idiomatic: "----4 Zhou Bo fully pacified Dai, Yanmen, and Yunzhong and beheaded Chen Xi at Dangcheng." },
  { zh: "----5上以荊王賈無後，更以荊為吳國。", literal: "----5 Because the King of Jing, Jia, had no heir, the Emperor changed Jing into the state of Wu.", idiomatic: "----5 Because King Jia of Jing had no heir, the Emperor made Jing into the state of Wu." },
  { zh: "辛丑，立兄仲之子濞為吳王，王三郡、五十三城。", literal: "On xinchou he established the son of his elder brother Zhong, Liu Pi, as King of Wu, ruling three commanderies and fifty-three cities.", idiomatic: "On xinchou he made his elder brother Zhong's son Liu Pi King of Wu, ruling three commanderies and fifty-three cities." },
  { zh: "----6十一月，上過魯，以太牢祠孔子。", literal: "----6 In the eleventh month the Emperor passed through Lu and sacrificed to Confucius with the grand offering.", idiomatic: "----6 In the eleventh month the Emperor passed through Lu and sacrificed to Confucius with the grand offering." },
  { zh: "----7上從破黥布歸，疾益甚，愈欲易太子。", literal: "----7 When the Emperor returned from defeating Qing Bu his illness grew worse and he wished all the more to replace the crown prince.", idiomatic: "----7 When the Emperor returned from defeating Qing Bu his illness grew worse and he wished all the more to replace the crown prince." },
  { zh: "張良諫不聽，因疾不視事。", literal: "Zhang Liang remonstrated but was not heeded; on account of illness he ceased attending to affairs.", idiomatic: "Zhang Liang remonstrated in vain and, pleading illness, ceased attending to affairs." },
  { zh: "叔孫通諫曰：「昔者晉獻公以驪姬之故，廢太子，立奚齊，晉國亂者數十年，為天下笑。", literal: "Shusun Tong remonstrated, saying, “Formerly Duke Xian of Jin, on account of Lady Li, deposed the crown prince and established Xi Qi; Jin was in disorder for several decades and became the laughingstock of the realm.", idiomatic: "Shusun Tong remonstrated: “Formerly Duke Xian of Jin, for Lady Li's sake, deposed his heir and made Xi Qi crown prince; Jin was torn by disorder for decades and became the world's laughingstock." },
  { zh: "秦以不蚤定扶蘇，令趙高得以詐立胡亥，自使滅祀，此陛下所親見。", literal: "Qin, because it did not early settle Fusu, allowed Zhao Gao to establish Huhai by fraud and thereby destroyed its sacrifices—this Your Majesty has seen with your own eyes.", idiomatic: "Qin, because it did not settle Fusu early, let Zhao Gao install Huhai by fraud and destroy its line—Your Majesty saw this yourself." },
  { zh: "今太子仁孝，天下皆聞之。", literal: "Now the crown prince is benevolent and filial; all the realm has heard of it.", idiomatic: "The crown prince is benevolent and filial; all the realm knows it." },
  { zh: "呂后與陛下攻苦食淡，其可背哉？", literal: "The Empress Lü and Your Majesty endured hardship and ate plain food—how could one turn one's back on that?", idiomatic: "The Empress Lü and Your Majesty endured hardship and ate plain fare—how could one betray that?" },
  { zh: "陛下必欲廢適而立少，臣願先伏誅，以頸血污地。", literal: "If Your Majesty must depose the heir and establish the younger son, your servant is willing to submit first to execution and stain the ground with the blood of his neck.", idiomatic: "If Your Majesty must depose the heir and install the younger son, your servant begs to die first and stain the ground with his neck's blood." },
  { zh: "」帝曰：「公罷矣，吾直戲耳。", literal: "” The Emperor said, “Stop, sir; I was only jesting.", idiomatic: "” The Emperor said, “Enough, sir—I was only jesting." },
  { zh: "」叔孫通曰：「太子，天下本，本一搖，天下振動；", literal: "” Shusun Tong said, “The crown prince is the root of the realm; if the root shakes once, the realm trembles;", idiomatic: "” Shusun Tong said, “The crown prince is the root of the realm; shake the root once and the realm trembles;" },
  { zh: "奈何以天下為戲乎？", literal: "how can you take the realm as a jest?", idiomatic: "how can you treat the realm as a jest?" },
  { zh: "」時大臣固爭者多；", literal: "” At that time many great ministers firmly remonstrated;", idiomatic: "” Many great ministers remonstrated firmly;" },
  { zh: "上知群臣心皆不附趙王，乃止不立。", literal: "the Emperor knew that in the ministers' hearts none favored the King of Zhao, and therefore stopped and did not install him.", idiomatic: "the Emperor saw that none of the ministers favored the King of Zhao and dropped the plan." },
  { zh: "----8相國何以長安地狹，上林中多空地，棄；", literal: "----8 The Chancellor, on account of Chang'an's narrow territory, [said that] in the Shanglin park there was much vacant land lying waste;", idiomatic: "----8 The Chancellor, because Chang'an's territory was cramped, [said that] much land in the Shanglin park lay vacant and wasted;" },
  { zh: "願令民得入田，毋收蒿，為禽獸食。", literal: "he wished to let the people enter and farm it, collecting no brushwood fees, [so it would be] food for birds and beasts.", idiomatic: "he wished to let the people farm it without brushwood fees, for birds and beasts to feed on." },
  { zh: "上大怒曰：「相國多受賈人財物，乃為請吾苑！", literal: "The Emperor was greatly angry and said, “The Chancellor has received much property from merchants and thus petitions My park for them!", idiomatic: "The Emperor was furious: “The Chancellor has taken so much from merchants that he petitions My park for them!" },
  { zh: "」下相國廷尉，械系之。", literal: "” He sent the Chancellor down to the commandant of justice and shackled and detained him.", idiomatic: "” He sent the Chancellor to the commandant of justice and had him shackled and detained." },
  { zh: "數日，王衛尉侍，前問曰：「相國何大罪，陛下系之暴也？", literal: "Several days later, Wang the commandant of the guard attended and stepped forward asking, “What great crime has the Chancellor committed that Your Majesty detained him so harshly?", idiomatic: "Days later Wang the commandant of the guard attended and asked, “What great crime has the Chancellor committed that Your Majesty detained him so harshly?" },
  { zh: "」上曰：「吾聞李斯相秦皇帝，有善歸主，有惡自與。", literal: "” The Emperor said, “I have heard that when Li Si served as chancellor to the First Emperor of Qin, what was good he attributed to the ruler and what was bad he took on himself.", idiomatic: "” The Emperor said, “I have heard that when Li Si served the First Emperor of Qin, he credited the ruler with good and took blame on himself." },
  { zh: "今相國多受賈豎金，而為之請吾苑以媚於民，故系治之。", literal: "Now the Chancellor has received much gold from merchant fellows and petitions My park on their behalf to curry favor with the people—therefore I detained and tried him.", idiomatic: "Now the Chancellor has taken much gold from merchants and petitions My park to curry favor with the people—that is why I detained him." },
  { zh: "」王衛尉曰：「夫職事苟有便於民而請之，真宰相事；", literal: "” Wang the commandant of the guard said, “If official duties happen to benefit the people and one petitions for that, it is truly a chancellor's business;", idiomatic: "” Wang the commandant of the guard said, “If an official duty benefits the people and one petitions for it, that is truly a chancellor's work;" },
  { zh: "陛下奈何乃疑相國受賈人錢乎？", literal: "how can Your Majesty suspect the Chancellor of receiving merchants' money?", idiomatic: "why should Your Majesty suspect the Chancellor of taking merchants' money?" },
  { zh: "且陛下距楚數歲，陳豨、黥布反，陛下自將而往；", literal: "Moreover Your Majesty was several years from Chu; when Chen Xi and Qing Bu rebelled, Your Majesty personally led [troops] and went;", idiomatic: "Moreover Your Majesty was years away fighting in Chu; when Chen Xi and Qing Bu rebelled, Your Majesty led the army in person;" },
  { zh: "當是時，相國守關中，關中搖足，則關以西非陛下有也！", literal: "at that time the Chancellor guarded Guanzhong—if Guanzhong stamped its foot, the lands west of the pass would no longer be Your Majesty's!", idiomatic: "then the Chancellor held Guanzhong—if Guanzhong stirred, everything west of the pass would no longer be Yours!" },
  { zh: "相國不以此時為利，今乃利賈人之金乎？", literal: "The Chancellor did not seek profit then—would he now profit from merchants' gold?", idiomatic: "The Chancellor did not profit then—would he profit from merchants' gold now?" },
  { zh: "且秦以不聞其過亡天下；", literal: "Moreover Qin lost the realm because its faults were not heard;", idiomatic: "Moreover Qin lost the realm because its faults went unheard;" },
  { zh: "李斯之分過，又何足法哉？", literal: "Li Si's apportioning of faults—how is that worth taking as a model?", idiomatic: "Li Si's way of shifting blame—what is there to emulate?" },
  { zh: "陛下何疑宰相之淺也！", literal: "How shallow is Your Majesty's suspicion of the chancellor!", idiomatic: "How shallow Your Majesty's suspicion of the chancellor!" },
  { zh: "」帝不懌。", literal: "” The Emperor was displeased.", idiomatic: "” The Emperor was displeased." },
  { zh: "是日，使使持節赦出相國。", literal: "That day he sent an envoy bearing credentials to pardon and release the Chancellor.", idiomatic: "That day he sent an envoy with credentials to pardon and release the Chancellor." },
  { zh: "相國年老，素恭謹，入，徒跣謝。", literal: "The Chancellor was old and always respectful and cautious; entering, he went barefoot to apologize.", idiomatic: "The Chancellor was old and always deferential; he came in barefoot to apologize." },
  { zh: "帝曰：「相國休矣！", literal: "The Emperor said, “Chancellor, rest!", idiomatic: "The Emperor said, “Chancellor, enough!" },
  { zh: "相國為民請苑，吾不許，我不過為桀、紂王，而相國為賢相。", literal: "The Chancellor petitioned for the park on the people's behalf and I did not grant it—I would have been no more than kings Jie and Zhou, while the Chancellor is a worthy chancellor.", idiomatic: "The Chancellor petitioned the park for the people and I refused—I would have been no better than Jie and Zhou, while the Chancellor proved himself worthy." },
  { zh: "吾故系相國，欲令百姓聞吾過也。", literal: "I therefore detained the Chancellor, wishing to let the common people hear of My fault.", idiomatic: "I detained the Chancellor so the people would hear of My fault." },
  { zh: "」----9陳豨之反也，燕王綰發兵擊其東北。", literal: "” ----9 When Chen Xi rebelled, the King of Yan, Liu Wan, sent troops to attack his northeast.", idiomatic: "” ----9 When Chen Xi rebelled, King Liu Wan of Yan sent troops against his northeast." },
  { zh: "當是時，陳豨使王黃求救匈奴；", literal: "At that time Chen Xi sent Wang Huang to beg rescue from the Xiongnu;", idiomatic: "At that time Chen Xi sent Wang Huang to beg the Xiongnu for aid;" },
  { zh: "燕王綰亦使其臣張勝於匈奴，言豨等軍破。", literal: "the King of Yan also sent his minister Zhang Sheng to the Xiongnu, saying Chen Xi's army was broken.", idiomatic: "King Liu Wan of Yan also sent his minister Zhang Sheng to the Xiongnu, reporting that Chen Xi's forces were broken." },
  { zh: "張勝至胡，故燕王藏荼子衍出亡在胡，見張勝曰：「公所以重於燕者，以習胡事也；", literal: "Zhang Sheng reached the Hu; Yan, the former King of Yan Zang Tu's son Yan, who had fled and was in exile among the Hu, saw Zhang Sheng and said, “The reason you are valued in Yan is that you are versed in Hu affairs;", idiomatic: "Zhang Sheng reached the Hu; Yan, son of the former King of Yan Zang Tu, who had fled into exile among the Hu, saw Zhang Sheng and said, “You are valued in Yan because you know Hu affairs;" },
  { zh: "燕所以久存者，以諸侯數反，兵連不決也。", literal: "Yan has long survived because the feudal lords have repeatedly rebelled and war drags on unresolved.", idiomatic: "Yan has lasted because the lords rebel again and again and war drags on without end." },
  { zh: "今公為燕，欲急滅豨等；", literal: "Now you act for Yan and wish to hurry to destroy Chen Xi and the rest;", idiomatic: "Now you act for Yan and wish to destroy Chen Xi and his men at once;" },
  { zh: "豨等已盡，次亦至燕，公等亦且為虜矣。", literal: "when Chen Xi and the rest are finished, next it will reach Yan—you too will soon be captives.", idiomatic: "when they are gone, Yan will be next—and you will soon be captives yourselves." },
  { zh: "公何不令燕且緩陳豨，而與胡和？", literal: "Why do you not have Yan for the present ease off on Chen Xi and make peace with the Hu?", idiomatic: "Why not have Yan hold back against Chen Xi for now and make peace with the Hu?" },
  { zh: "事寬，得長王燕；", literal: "If matters are relaxed, you can long rule Yan;", idiomatic: "If matters ease, you can rule Yan for long;" },
  { zh: "即有漢急，可以安國。", literal: "if there is urgency from Han, you can secure the state.", idiomatic: "if Han presses hard, you can still secure your state." },
  { zh: "」張勝以為然，乃私令匈奴助豨等擊燕。", literal: "” Zhang Sheng thought it right and secretly ordered the Xiongnu to help Chen Xi and the rest attack Yan.", idiomatic: "” Zhang Sheng agreed and secretly ordered the Xiongnu to help Chen Xi attack Yan." },
  { zh: "燕王綰疑張勝與胡反，上書請族張勝。", literal: "The King of Yan suspected Zhang Sheng of turning against him with the Hu and memorialized asking to execute Zhang Sheng's clan by degrees.", idiomatic: "King Liu Wan suspected Zhang Sheng of colluding with the Hu and memorialized to wipe out Zhang Sheng's clan." },
  { zh: "勝還，具道所以為者；", literal: "Sheng returned and fully explained why he had done it;", idiomatic: "Sheng returned and explained fully what he had done;" },
  { zh: "燕王乃詐論他人，脫勝家屬，使得為匈奴間。", literal: "the King of Yan then falsely indicted others, exonerated Sheng's kin, and let him serve as a spy for the Xiongnu.", idiomatic: "the king then framed others, freed Sheng's kin, and let him serve as a Xiongnu spy." },
  { zh: "而陰使范齊之陳豨所，欲令久亡，連兵勿決。", literal: "and secretly sent Fan Qi to Chen Xi's camp, wishing to make the war long unsettled and the armies linked without resolution.", idiomatic: "and secretly sent Fan Qi to Chen Xi's camp to prolong the war and keep the armies locked without decision." },
  { zh: "漢擊黥布，豨常將兵居代；", literal: "When Han attacked Qing Bu, Xi often held troops stationed in Dai;", idiomatic: "While Han attacked Qing Bu, Xi often held troops in Dai;" },
  { zh: "漢擊斬豨，其裨將降，言燕王綰使范齊通計謀於豨所。", literal: "when Han attacked and beheaded Xi, his lieutenant general surrendered and said the King of Yan Liu Wan had sent Fan Qi to pass plans with Xi.", idiomatic: "when Han attacked and killed Xi, a lieutenant general surrendered and said King Liu Wan of Yan had sent Fan Qi to Chen Xi with plans." },
  { zh: "帝使使召盧綰，綰稱病；", literal: "The Emperor sent an envoy to summon Liu Wan; Wan claimed illness;", idiomatic: "The Emperor sent to summon Liu Wan; Wan claimed illness;" },
  { zh: "上又使辟陽侯審食其、御史大夫趙堯往迎燕王，因驗問左右。", literal: "the Emperor again sent Marquis of Piyang Shen Yishi and the grand secretary Zhao Yao to go and welcome the King of Yan, and thereby investigate and question those around him.", idiomatic: "the Emperor again sent Marquis of Piyang Shen Yishi and Grand Secretary Zhao Yao to welcome the King of Yan and question his attendants." },
  { zh: "綰愈恐，閉匿，謂其幸臣曰：「非劉氏而王，獨我與長沙耳。", literal: "Wan grew ever more afraid, shut himself in hiding, and said to his favored ministers, “Of those made kings who are not of the Liu clan, only I and Changsha remain.", idiomatic: "Wan grew more afraid, shut himself away, and told his favorites, “Of non-Liu kings, only I and Changsha remain." },
  { zh: "往年春，漢族淮陰，夏，誅彭越，皆呂氏計。", literal: "In spring of the past year Han destroyed the clan of Huaiyin by degrees; in summer Peng Yue was executed—all Lü clan schemes.", idiomatic: "Last spring Han wiped out Huaiyin's clan; in summer Peng Yue was executed—all the Lü clan's doing." },
  { zh: "令上病，屬任呂后；", literal: "The Emperor is ill and entrusts affairs to Empress Lü;", idiomatic: "The Emperor is ill and has entrusted power to Empress Lü;" },
  { zh: "呂后婦人，專欲以事誅異姓王者及大功臣。", literal: "Empress Lü is a woman and aims solely to use occasions to execute kings of other surnames and great merit-holders.", idiomatic: "Empress Lü is a woman bent on finding pretexts to kill non-Liu kings and great merit-holders." },
  { zh: "」乃遂稱病不行，其左右皆亡匿。", literal: "” Thereupon he claimed illness and would not go; his attendants all fled and hid.", idiomatic: "” He then pleaded illness and would not go; his attendants all fled into hiding." },
  { zh: "語頗洩，辟陽侯聞之，歸，具報上，上益怒。", literal: "Word leaked somewhat; Shen Yishi heard, returned, and fully reported to the Emperor; the Emperor grew angrier.", idiomatic: "Word leaked; Shen Yishi heard, returned, and reported in full; the Emperor grew angrier." },
  { zh: "又得匈奴降者，言張勝亡在匈奴為燕使。", literal: "He also obtained a Xiongnu defector who said Zhang Sheng had fled to the Xiongnu and served as Yan's envoy.", idiomatic: "A Xiongnu defector also said Zhang Sheng had fled to the Xiongnu as Yan's envoy." },
  { zh: "於是上曰：「盧綰果反矣！", literal: "Thereupon the Emperor said, “Liu Wan has truly rebelled!", idiomatic: "The Emperor then said, “Liu Wan has truly rebelled!" },
  { zh: "」春，二月，使樊噲以相國將兵擊綰，立皇子建為燕王。", literal: "” In spring, the second month, he sent Fan Kuai as chancellor commanding troops to attack Wan and established the imperial son Jian as King of Yan.", idiomatic: "” In spring, the second month, he sent Fan Kuai as chancellor to attack Wan and made his son Jian King of Yan." },
  { zh: "----10詔曰：「南武侯織，亦粵之世也，立以為南海王。", literal: "----10 An edict said, “Marquis of Nanwu Zhi is also of Yue's line; establish him as King of Nanhai.", idiomatic: "----10 An edict said, “Marquis of Nanwu Zhi is also of Yue's line; establish him as King of Nanhai." },
  { zh: "」----11上擊布時，為流矢所中，行道，疾甚。", literal: "” ----11 When the Emperor attacked Bu he was struck by a stray arrow; on the march his illness grew severe.", idiomatic: "” ----11 When the Emperor attacked Bu he was struck by a stray arrow; on the march his illness grew grave." },
  { zh: "呂后迎良醫。", literal: "Empress Lü summoned a skilled physician.", idiomatic: "Empress Lü summoned a skilled physician." },
  { zh: "醫入見，曰：「疾可治。", literal: "The physician entered and saw him and said, “The illness can be cured.", idiomatic: "The physician came in and said, “The illness can be cured." },
  { zh: "」上嫚罵之曰：「吾以布衣提三尺取天下，此非天命乎？", literal: "” The Emperor scornfully reviled him, saying, “I took the realm in plain cloth raising three feet [of steel]—is this not Heaven's mandate?", idiomatic: "” The Emperor scornfully cursed him: “I took the realm as a commoner with a three-foot sword—is that not Heaven's mandate?" },
  { zh: "命乃在天，雖扁鵲何益？", literal: "Fate is in Heaven—what use even Bian Que?", idiomatic: "Fate lies with Heaven—what use is even Bian Que?" },
  { zh: "」遂不使治疾，賜黃金五十斤，罷之。", literal: "” He then would not let him treat the illness, bestowed fifty jin of gold, and dismissed him.", idiomatic: "” He would not let him treat the illness, gave him fifty jin of gold, and sent him away." },
  { zh: "呂后問曰：「陛下百歲後，蕭相國既死，誰令代之？", literal: "Empress Lü asked, “After Your Majesty's hundred years, when Chancellor Xiao is dead, who shall replace him?", idiomatic: "Empress Lü asked, “After Your Majesty passes, when Chancellor Xiao is gone, who should replace him?" },
  { zh: "」上曰：「曹參可。", literal: "” The Emperor said, “Cao Shen will do.", idiomatic: "” The Emperor said, “Cao Shen." },
  { zh: "」問其次，曰：「王陵可，然少戇，陳平可以助之。", literal: "” Asked for the next, he said, “Wang Ling will do, but he is somewhat blunt and simple; Chen Ping can assist him.", idiomatic: "” Asked who was next, he said, “Wang Ling, though he is somewhat blunt; Chen Ping can assist him." },
  { zh: "陳平知有餘，然難獨任。", literal: "Chen Ping's knowledge has surplus, yet he is hard to entrust alone.", idiomatic: "Chen Ping's talents exceed what is needed, yet he is hard to entrust alone." },
  { zh: "周勃重厚少文，然安劉氏者必勃也，可令為太尉。", literal: "Zhou Bo is weighty, thick, and short on polish, yet he who will secure the Liu clan must be Bo; he may be made grand commandant.", idiomatic: "Zhou Bo is stolid and unpolished, yet whoever secures the Liu clan will be Bo; make him grand commandant." },
  { zh: "」呂后復問其次，上曰：「此後亦非乃所知也。", literal: "” Empress Lü again asked for the next; the Emperor said, “Beyond this is not for you to know.", idiomatic: "” Empress Lü asked again; the Emperor said, “Beyond that is not for you to know." },
  { zh: "」夏，四月，甲辰，帝崩於長樂宮。", literal: "” In summer, the fourth month, on jiachen the Emperor died at Changle Palace.", idiomatic: "” In summer, the fourth month, on jiachen the Emperor died at Changle Palace." },
  { zh: "丁未，發喪，大赦天下。", literal: "On dingwei the mourning was proclaimed and a great amnesty was granted to the realm.", idiomatic: "On dingwei mourning was proclaimed and the realm was granted a great amnesty." },
  { zh: "----12盧綰與數千人居塞下候伺，幸上疾愈，自入謝。", literal: "----12 Liu Wan with several thousand men dwelt below the passes watching, hoping the Emperor's illness would heal so he could enter in person to apologize.", idiomatic: "----12 Liu Wan with several thousand men waited below the passes, hoping the Emperor would recover so he could come in person to apologize." },
  { zh: "聞帝崩，遂亡入匈奴。", literal: "Hearing the Emperor had died, he then fled and entered the Xiongnu.", idiomatic: "Hearing the Emperor had died, he fled into the Xiongnu." },
  { zh: "----13五月，丙寅，葬高帝於長陵。", literal: "----13 In the fifth month, on bingyin, the High Emperor was buried at Changling.", idiomatic: "----13 In the fifth month, on bingyin, the High Emperor was buried at Changling." },
  { zh: "初，高祖不修文學，而性明達，好謀，能聽，自監門、戍卒，見之如舊。", literal: "At first, the High Ancestor did not cultivate literary learning, yet his nature was clear and penetrating; he loved counsel, could listen, and from gatekeepers to garrison soldiers, seeing them was as of old.", idiomatic: "At first the High Ancestor did not cultivate letters, yet he was clear-sighted, loved counsel, and listened well; from gatekeepers to garrison soldiers he treated old acquaintances as before." },
  { zh: "初順民心作三章之約。", literal: "At first he followed the people's hearts in making the Three-Article Covenant.", idiomatic: "At first he followed the people's will in making the Three-Article Covenant." },
  { zh: "天下既定，命蕭何次律、令，韓信申軍法，張蒼定章程，叔孫通制禮儀；", literal: "When the realm was settled he ordered Xiao He to arrange laws and ordinances, Han Xin to set forth military law, Zhang Cang to fix regulations and statutes, and Shusun Tong to establish ritual observances;", idiomatic: "When the realm was settled he had Xiao He compile laws and ordinances, Han Xin set forth military law, Zhang Cang fix regulations and statutes, and Shusun Tong establish ritual observances;" },
  { zh: "又與功臣剖符作誓，丹書、鐵契，金匱、石室，藏之宗廟。", literal: "he also with the merit-holders split tally-fish and made oaths—red writing on iron contracts, gold caskets and stone chambers—and stored them in the ancestral temple.", idiomatic: "he also split tally-fish with the merit-holders and swore oaths—red writing on iron contracts, gold caskets and stone chambers—and stored them in the ancestral temple." },
  { zh: "雖日不暇給，規摹弘遠矣。", literal: "Though day by day there was no leisure, the plan and measure were vast and far-reaching.", idiomatic: "Though day by day left no leisure, the design was vast and far-reaching." },
  { zh: "----14己巳，太子即皇帝位，尊皇后曰皇太后。", literal: "----14 On jisi the crown prince assumed the imperial throne and honored the empress as empress dowager.", idiomatic: "----14 On jisi the crown prince took the throne and honored the empress as empress dowager." },
  { zh: "----15初，高帝病甚，人有惡樊噲，云：「黨於呂氏，即一日上晏駕，欲以兵誅趙王如意之屬。", literal: "----15 At first, when the High Emperor was gravely ill, someone spoke ill of Fan Kuai, saying, “He is partisan to the Lü clan; if one day the Emperor passes, he wishes with troops to execute the King of Zhao Ruyi and his sort.", idiomatic: "----15 When the High Emperor was gravely ill, someone slandered Fan Kuai, saying, “He sides with the Lü clan; when the Emperor passes he means to use troops to kill King Ruyi of Zhao and his kin." },
  { zh: "」帝大怒，用陳平謀，召絳侯周勃受詔床下，曰：「陳平亟馳傳載勃代噲將；", literal: "” The Emperor was greatly angry; using Chen Ping's plan he summoned Marquis of Jiang Zhou Bo to receive the edict beneath the bed, saying, “Chen Ping, speed relay horses, take Bo and replace Kuai as general;", idiomatic: "” The Emperor was furious; using Chen Ping's plan he summoned Marquis of Jiang Zhou Bo to take the edict beneath the bed: “Chen Ping, take relay horses at once, bring Bo, and replace Kuai as general;" },
  { zh: "平至軍中，即斬噲頭！", literal: "when Ping reaches the army, at once behead Kuai!", idiomatic: "when Ping reaches the army, behead Kuai at once!" },
  { zh: "」二人既受詔，馳傳，未至軍，行計之曰：「樊噲，帝之故人也，功多，且又呂后弟呂嬃之夫，有親且貴。", literal: "” The two, having received the edict, galloped relay; before reaching the army, en route they calculated, saying, “Fan Kuai is an old man of the Emperor's, his merit great, and moreover husband to Empress Lü's brother Lü Xu'ou's daughter—close kin and noble.", idiomatic: "” The two took the edict and galloped relay; before reaching the army they reasoned: “Fan Kuai is an old companion of the Emperor, his merit great, and husband to Empress Lü's brother Lü Xu'ou's daughter—close kin and high in rank." },
  { zh: "帝以仇怒故欲斬之，則恐後悔；", literal: "The Emperor, from enmity and anger, wishes to behead him—then we fear he will regret it;", idiomatic: "The Emperor, in anger and enmity, wants him killed—we fear he will regret it;" },
  { zh: "寧囚而致上，上自誅之。", literal: "better to imprison him and present him to the Emperor; the Emperor himself will execute him.", idiomatic: "better to imprison him and present him to the Emperor and let the Emperor kill him himself." },
  { zh: "」未至軍，為壇，以節召樊噲。", literal: "” Before reaching the army they made an altar and with credentials summoned Fan Kuai.", idiomatic: "” Before reaching the army they built an altar and summoned Fan Kuai with credentials." },
  { zh: "噲受詔，即反接，載檻車傳詣長安；", literal: "Kuai received the edict and at once was bound arms back, loaded on a caged cart, and relayed to Chang'an;", idiomatic: "Kuai received the edict and was bound at once, loaded on a caged cart, and relayed to Chang'an;" },
  { zh: "而令絳侯勃代將，將兵定燕反縣。", literal: "and they ordered Marquis of Jiang Bo to replace him as general and lead troops to settle the rebel counties of Yan.", idiomatic: "and had Marquis of Jiang Bo replace him and lead troops to pacify Yan's rebel counties." },
  { zh: "平行，聞帝崩，畏呂嬃讒之於太后，乃馳傳先去。", literal: "Ping traveled on; hearing the Emperor had died, fearing Lü Xu'ou would slander him to the empress dowager, he galloped relay and went ahead first.", idiomatic: "Ping went on; hearing the Emperor had died, fearing Lü Xu'ou would slander him to the empress dowager, he galloped ahead by relay." },
  { zh: "逢使者，詔平與灌嬰屯滎陽。", literal: "Meeting an envoy, [received] an edict [for] Ping and Guan Ying to garrison Xingyang.", idiomatic: "He met an envoy with an edict for Ping and Guan Ying to garrison Xingyang." },
  { zh: "平受詔，立復馳至宮，哭殊悲；", literal: "Ping received the edict, at once galloped again to the palace, and wept exceedingly sadly;", idiomatic: "Ping took the edict, galloped straight back to the palace, and wept with extraordinary grief;" },
  { zh: "因固請得宿衛中。", literal: "thereby firmly requesting to be lodged in the inner guard.", idiomatic: "and firmly asked to lodge in the inner guard." },
  { zh: "太后乃以為郎中令，使傅教惠帝。", literal: "The empress dowager then made him director of the palace gentlemen and had him tutor and teach Emperor Hui.", idiomatic: "The empress dowager then made him director of the palace gentlemen to tutor and instruct Emperor Hui." },
  { zh: "是後呂嬃讒乃不得行。", literal: "After this Lü Xu'ou's slander could not be carried out.", idiomatic: "After that Lü Xu'ou's slander could not proceed." },
  { zh: "樊噲至，則赦，復爵邑。", literal: "Fan Kuai arrived and was then pardoned; his noble rank and fief were restored.", idiomatic: "When Fan Kuai arrived he was pardoned and his rank and fief restored." },
  { zh: "----16太后令永巷囚戚夫人，髡鉗，衣赭衣，令舂。", literal: "----16 The empress dowager ordered Lady Qi imprisoned in the everlasting alleys, shorn and shackled, clad in ochre robes, and made to pound grain.", idiomatic: "----16 The empress dowager had Lady Qi imprisoned in the everlasting alleys, shorn and shackled, dressed in ochre robes, and set to pounding grain." },
  { zh: "遣使召趙王如意。", literal: "She sent an envoy to summon the King of Zhao, Ruyi.", idiomatic: "She sent an envoy to summon King Ruyi of Zhao." },
  { zh: "使者三反，趙相周昌謂使者曰：「高帝屬臣趙王，趙王年少，竊聞太后怨戚夫人，欲召趙王並誅之，臣不敢遣王。", literal: "The envoy returned three times; the chancellor of Zhao Zhou Chang told the envoy, “The High Emperor entrusted the King of Zhao to me; the King of Zhao is young. I privately hear the empress dowager resents Lady Qi and wishes to summon the King of Zhao and execute him together—I dare not send the king.", idiomatic: "The envoy came three times; Chancellor of Zhao Zhou Chang told him, “The High Emperor entrusted the King of Zhao to me; the king is young. I hear the empress dowager resents Lady Qi and means to summon the King of Zhao and kill him with her—I dare not send the king." },
  { zh: "王且亦病，不能奉詔。", literal: "The king is moreover ill and cannot obey the edict.", idiomatic: "The king is also ill and cannot obey the edict." },
  { zh: "」太后怒，先使人召昌。", literal: "” The Empress Dowager was angry and first sent men to summon Chang.", idiomatic: "” The Empress Dowager was furious and first sent men to summon Zhou Chang." },
  { zh: "昌至長安，乃使人復召趙王。", literal: "When Chang reached Chang'an, she then sent men again to summon the King of Zhao.", idiomatic: "Once Chang reached Chang'an, she sent men again to summon the King of Zhao." },
  { zh: "王來，未到；", literal: "The king came but had not yet arrived;", idiomatic: "The king set out but had not yet arrived;" },
  { zh: "帝知太后怒，自迎趙王霸上，與入宮，自挾與起居飲食。", literal: "the Emperor, knowing the Empress Dowager was angry, went himself to meet the King of Zhao at Bashang, entered the palace with him, and personally held him close in rising, resting, eating, and drinking.", idiomatic: "the Emperor, knowing the Empress Dowager was angry, went himself to meet the King of Zhao at Bashang, brought him into the palace, and personally kept him at his side day and night for meals and daily life." },
  { zh: "太后欲殺之，不得間。", literal: "The Empress Dowager wished to kill him but found no opening.", idiomatic: "The Empress Dowager wished to kill him but found no opportunity." },
  { zh: "1冬，十二月，帝晨出射。", literal: "1 In winter, the twelfth month, the Emperor went out early to shoot.", idiomatic: "1 In winter, the twelfth month, the Emperor went out early to hunt." },
  { zh: "趙王少，不能蚤起；", literal: "The King of Zhao was young and could not rise early;", idiomatic: "The King of Zhao was young and could not rise early;" },
  { zh: "太后使人持鴆飲之。", literal: "the Empress Dowager sent men bearing poison wine to make him drink it.", idiomatic: "the Empress Dowager sent men with poisoned wine and made him drink it." },
  { zh: "犁明，帝還，趙王已死。", literal: "At dawn the Emperor returned; the King of Zhao was already dead.", idiomatic: "At dawn the Emperor returned and found the King of Zhao already dead." },
  { zh: "太后遂斷戚夫人手足，去眼，煇耳，飲喑藥，使居廁中，命曰「人彘」。", literal: "The Empress Dowager then cut off Lady Qi's hands and feet, removed her eyes, scorched her ears, made her drink a mute drug, and had her dwell in the privy, naming her “human swine.”", idiomatic: "The Empress Dowager then cut off Lady Qi's hands and feet, gouged out her eyes, deafened her ears, forced a drug that left her mute, and had her kept in the privy, calling her “the human swine.”" },
  { zh: "居數日，乃召帝觀人彘。", literal: "After several days she summoned the Emperor to view the human swine.", idiomatic: "After several days she summoned the Emperor to see the human swine." },
  { zh: "帝見，問知其戚夫人，乃大哭，因病，歲餘不能起。", literal: "The Emperor saw her, asked and knew it was Lady Qi, then wept greatly, fell ill, and for more than a year could not rise.", idiomatic: "The Emperor saw her, learned it was Lady Qi, and wept bitterly; he fell ill and for more than a year could not get up." },
  { zh: "使人請太后曰：「此非人所為。", literal: "He sent someone to tell the Empress Dowager, saying, “This is not what a human being would do.", idiomatic: "He sent someone to tell the Empress Dowager: “This is not what a human being would do." },
  { zh: "臣為太后子，終不能治天下。", literal: "I am Your Majesty's son as empress, yet in the end I cannot govern All under Heaven.", idiomatic: "I am Your Majesty's son, yet in the end I cannot govern the realm." },
  { zh: "」帝以此日飲為淫樂，不聽政。", literal: "” From that day the Emperor took drink as dissolute pleasure and would not attend to government.", idiomatic: "” From that day the Emperor drowned himself in wine and pleasure and ceased to attend to government." },
  { zh: "::臣光曰：為人子者，父母有過則諫；", literal: ":: Your servant Guang says: As a son, when parents have faults one should remonstrate;", idiomatic: ":: Your servant Guang says: As a son, when parents err one should remonstrate;" },
  { zh: "諫而不聽，則號泣而隨之。", literal: "if remonstrance is not heeded, then weep and wail and follow them.", idiomatic: "if they will not listen, then weep and follow them." },
  { zh: "安有守高祖之業，為天下之主，不忍母之殘酷，遂棄國家而不恤，縱酒色以傷生？", literal: "How can one hold fast to the High Ancestor's enterprise, be lord of All under Heaven, be unable to bear his mother's cruelty, then cast aside the state without care and indulge in wine and women to harm one's life?", idiomatic: "How can one hold the High Ancestor's legacy, be lord of the realm, unable to bear his mother's cruelty, then abandon the state without a thought and indulge in wine and women to ruin one's health?" },
  { zh: "若孝惠者，可謂篤於小仁而未知大誼也。", literal: "One such as Emperor Hui may be called deep in petty benevolence yet ignorant of great principle.", idiomatic: "Emperor Hui may be called devoted to petty kindness yet ignorant of great duty." },
  { zh: "----2徙淮陽王友為趙王。", literal: "----2 The King of Huaiyang, You, was moved to be King of Zhao.", idiomatic: "----2 King You of Huaiyang was transferred to be King of Zhao." },
  { zh: "----3春，正月，始作長安城西北方。", literal: "----3 In spring, the first month, work began on the northwest section of Chang'an's walls.", idiomatic: "----3 In spring, the first month, construction began on the northwest section of Chang'an's walls." },
  { zh: "1冬，十月，齊悼惠王來朝，飲於太后前。", literal: "1 In winter, the tenth month, the King of Qi, Daohui, came to court and drank before the Empress Dowager.", idiomatic: "1 In winter, the tenth month, King Daohui of Qi came to court and drank in the Empress Dowager's presence." },
  { zh: "帝以齊王，兄也，置之上坐。", literal: "The Emperor, taking the King of Qi as his elder brother, seated him in the seat of honor.", idiomatic: "The Emperor, treating the King of Qi as his elder brother, gave him the seat of honor." },
  { zh: "太后怒，酌鴆酒置前，賜齊王為壽。", literal: "The Empress Dowager was angry, poured poison wine and set it before him, and bestowed it on the King of Qi to wish him long life.", idiomatic: "The Empress Dowager was angry, poured poison wine, set it before him, and offered it to the King of Qi as a toast for long life." },
  { zh: "齊王起，帝亦起取卮；", literal: "The King of Qi rose; the Emperor also rose to take the cup;", idiomatic: "The King of Qi rose; the Emperor rose as well to take the cup;" },
  { zh: "太后恐，自起泛帝卮。", literal: "the Empress Dowager was afraid and herself rose to spill the Emperor's cup.", idiomatic: "the Empress Dowager was alarmed and rose herself to spill the Emperor's cup." },
  { zh: "齊王怪之，因不敢飲，佯醉去；", literal: "The King of Qi thought it strange and therefore dared not drink, feigned drunkenness and left;", idiomatic: "The King of Qi found it strange, dared not drink, feigned drunkenness, and left;" },
  { zh: "問知其鴆，大恐。", literal: "on inquiry learned it was poison and was greatly afraid.", idiomatic: "and on inquiry learned it was poisoned—he was terrified." },
  { zh: "齊內史士說王，使獻城陽郡為魯元公主湯沐邑。", literal: "The interior secretary of Qi admonished the king and had him present Chengyang commandery as Princess Yuan of Lu's fief for bathing and grooming.", idiomatic: "Qi's interior secretary admonished the king and had him offer Chengyang commandery as Princess Yuan of Lu's fief." },
  { zh: "太后喜，乃罷歸齊王。", literal: "The Empress Dowager was pleased and then dismissed him and sent the King of Qi home.", idiomatic: "The Empress Dowager was pleased and let the King of Qi return to Qi." },
  { zh: "----2春，正月，癸酉，有兩龍見蘭陵家人井中。", literal: "----2 In spring, the first month, on guiyou, two dragons appeared in a commoner's well at Lanling.", idiomatic: "----2 In spring, the first month, on guiyou, two dragons were seen in a commoner's well at Lanling." },
  { zh: "----3隴西地震。", literal: "----3 Longxi suffered an earthquake.", idiomatic: "----3 Longxi was shaken by an earthquake." },
  { zh: "----4夏，旱。", literal: "----4 In summer there was drought.", idiomatic: "----4 In summer there was drought." },
  { zh: "----5郃陽侯仲薨。", literal: "----5 Marquis of Heyang, Zhong, died.", idiomatic: "----5 Marquis of Heyang Zhong died." },
  { zh: "----6酇文終侯蕭何病，上親自臨視，因問曰：「君即百歲後，誰可代君者？", literal: "----6 Marquis of Pei, Wenzhong, Xiao He was ill; the Emperor personally went to visit him and asked, saying, “When you reach a hundred years, who can replace you?", idiomatic: "----6 Marquis of Pei Wenzhong Xiao He fell ill; the Emperor visited him in person and asked, “When you are gone, who can replace you?" },
  { zh: "」對曰：「知臣莫如主。", literal: "” He replied, saying, “No one knows a minister like his lord.", idiomatic: "” He replied, “No one knows a minister like his lord." },
  { zh: "」帝曰：「曹參何如？", literal: "” The Emperor said, “How about Cao Shen?", idiomatic: "” The Emperor said, “What of Cao Shen?" },
  { zh: "」何頓首曰：「帝得之矣，臣死不恨！", literal: "” He kowtowed and said, “Your Majesty has got the right man; I die without regret!", idiomatic: "” He kowtowed and said, “Your Majesty has the right man; I die without regret!" },
  { zh: "秋，七月，辛未，何薨。", literal: "In autumn, the seventh month, on xinwei, He died.", idiomatic: "In autumn, the seventh month, on xinwei, Xiao He died." },
  { zh: "何置田宅，必居窮僻處，為家，不治垣屋。", literal: "When He set up fields and houses he always dwelt in poor and remote places; as head of the family he did not repair walls and roofs.", idiomatic: "When Xiao He acquired land and houses he always chose poor, remote sites; as head of the household he would not build high walls or fine roofs." },
  { zh: "曰：「後世賢，師吾儉；", literal: "He said, “If later generations are worthy, take me as teacher in thrift;", idiomatic: "He said, “If later generations are worthy, let them learn thrift from me;" },
  { zh: "不賢，毋為勢家所奪。", literal: "if unworthy, let them not be seized by powerful families.", idiomatic: "if unworthy, let them not be seized by powerful families." },
  { zh: "癸巳，以曹參為相國。", literal: "On guisi, Cao Shen was made chancellor of state.", idiomatic: "On guisi, Cao Shen was appointed chancellor of state." },
  { zh: "參聞何薨，告舍人：「趣治行！", literal: "When Shen heard that He had died, he told his retainers, “Hurry and pack for the journey!", idiomatic: "When Shen heard Xiao He had died, he told his retainers, “Pack at once for the journey!" },
  { zh: "吾將入相。", literal: "I am about to enter the capital as chancellor.", idiomatic: "I am about to become chancellor." },
  { zh: "」居無何，使者果召參。", literal: "” Before long an envoy indeed summoned Shen.", idiomatic: "” Before long an envoy did summon Shen." },
  { zh: "始，參微時，與蕭何善；", literal: "At first, when Shen was in humble circumstances, he and Xiao He were on good terms;", idiomatic: "Early on, when Shen was still obscure, he and Xiao He were close;" },
  { zh: "及為將相，有隙；", literal: "when they became general and chancellor there was a rift;", idiomatic: "when they became general and chancellor they fell out;" },
  { zh: "至何且死，所推賢唯參。", literal: "but when He was about to die, the worthy man he recommended was only Shen.", idiomatic: "yet when Xiao He was dying, the worthy man he recommended was Shen alone." },
  { zh: "參代何為相，舉事無所變更，一遵何約束：擇郡國吏木訥於文辭、重厚長者，即召除為丞相史；", literal: "Shen replaced He as chancellor; in all affairs he made no changes and followed He's regulations entirely: he chose commandery and state clerks who were wooden and slow in literary phrasing, men of weight and long standing, and at once summoned and appointed them as the chancellor's clerks;", idiomatic: "Shen succeeded Xiao He as chancellor; he changed nothing and followed Xiao He's rules entirely: he chose commandery and state officials who were plain and awkward in rhetoric, men of substance and long experience, and at once summoned them to be the chancellor's clerks;" },
  { zh: "吏之言文刻深、欲務聲名者，輒斥去之。", literal: "clerks whose words were literary, harsh, and deep, who wished to pursue reputation, he at once dismissed.", idiomatic: "officials who spoke in sharp, ornate prose and sought fame he promptly dismissed." },
  { zh: "日夜飲醇酒。", literal: "Day and night he drank strong wine.", idiomatic: "Day and night he drank strong wine." },
  { zh: "卿、大夫以下吏及賓客見參不事事，來者皆欲有言，參輒飲以醇酒；", literal: "When clerks, grandees, and subordinate officials and guests saw that Shen did not attend to affairs and came wishing to speak, Shen would at once ply them with strong wine;", idiomatic: "When ministers, grandees, subordinate officials, and guests saw that Shen attended to nothing and came wishing to speak, he at once plied them with strong wine;" },
  { zh: "間欲有所言，復飲之，醉而後去，終莫得開說，以為常。", literal: "if in the interval they wished to say something, he would drink them again; when drunk they would leave—in the end none could open their case, and this became the norm.", idiomatic: "if they still wished to speak, he would ply them again; they left drunk and never got to make their point—this became routine." },
  { zh: "見人有細過，專掩匿覆蓋之，府中無事。", literal: "When he saw men with small faults he would specially conceal and cover them; in the office there was no trouble.", idiomatic: "When he saw minor faults he would cover them up; the chancellor's office was untroubled." },
  { zh: "參子窋為中大夫。", literal: "Shen's son Zhu was a palace grandee.", idiomatic: "Shen's son Zhu was a palace grandee." },
  { zh: "帝怪相國不治事，以為「豈少朕與？", literal: "The Emperor wondered that the chancellor of state did not govern affairs and thought, “Does he think me too young?", idiomatic: "The Emperor wondered that the chancellor neglected affairs and thought, “Does he think I am too young?" },
  { zh: "」使窋歸，以其私問參。", literal: "” He sent Zhu home to question Shen privately.", idiomatic: "” He sent Zhu home to question Shen privately." },
  { zh: "參怒，笞窋二百，曰：「趣入侍！", literal: "Shen was angry and flogged Zhu two hundred strokes, saying, “Hurry back to attend at court!", idiomatic: "Shen was furious and flogged Zhu two hundred strokes, saying, “Get back to court at once!" },
  { zh: "天下事非若所當言也！", literal: "Affairs of All under Heaven are not what you ought to speak of!", idiomatic: "Affairs of the realm are not for you to discuss!" },
  { zh: "」至朝時，帝讓參曰：「乃者我使諫君也。", literal: "” When he came to court the Emperor reproached Shen, saying, “Just now I had you admonish your father.", idiomatic: "” At court the Emperor reproached Shen: “Just now I had you admonish your father." },
  { zh: "」參免冠謝曰：「陛下自察聖武孰與高帝？", literal: "” Shen removed his cap and apologized, saying, “Your Majesty, consider for yourself—whose sagely martial prowess compares with the High Emperor's?", idiomatic: "” Shen removed his cap and apologized: “Your Majesty, consider—whose sagely prowess compares with the High Emperor's?" },
  { zh: "」上曰：「朕乃安敢望先帝！", literal: "” The Emperor said, “How would I dare look to the late Emperor!", idiomatic: "” The Emperor said, “How would I dare compare myself to the late Emperor!" },
  { zh: "」又曰：「陛下觀臣能孰與蕭何賢？", literal: "” He said again, “Your Majesty, consider—whose ability compares with Xiao He's worth?", idiomatic: "” He said again, “Your Majesty, consider—whose ability compares with Xiao He's?" },
  { zh: "」上曰：「君似不及也。", literal: "” The Emperor said, “You seem not to reach him.", idiomatic: "” The Emperor said, “You seem not to match him." },
  { zh: "」參曰：「陛下言之是也。", literal: "” Shen said, “Your Majesty speaks rightly.", idiomatic: "” Shen said, “Your Majesty speaks rightly." },
  { zh: "高帝與蕭何定天下，法令既明。", literal: "The High Emperor and Xiao He settled All under Heaven; the laws and orders are already clear.", idiomatic: "The High Emperor and Xiao He settled the realm; the laws are already clear." },
  { zh: "今陛下垂拱，參等守職，遵而勿失，不亦可乎？", literal: "Now Your Majesty sits with hands folded; Shen and others keep their posts, hold fast and do not lose them—is that not acceptable?", idiomatic: "Now Your Majesty reigns at ease; Shen and the rest keep their posts and hold to what was established without loss—is that not enough?" },
  { zh: "」帝曰：「善！", literal: "” The Emperor said, “Good!", idiomatic: "” The Emperor said, “Good!" },
  { zh: "參為相國，出入三年，百姓歌之曰：「蕭何為法，較若畫一；", literal: "Shen served as chancellor of state, coming and going for three years; the people sang of him, saying, “Xiao He made the law, uniform as if drawn with one stroke;", idiomatic: "Shen served as chancellor for three years; the people sang: “Xiao He made the laws, uniform as if drawn with one stroke;" },
  { zh: "曹參代之，守而勿失。", literal: "Cao Shen replaced him and kept them without loss.", idiomatic: "Cao Shen replaced him and kept them without loss." },
  { zh: "載其清淨，民以寧壹。", literal: "He carried on that purity and quiet; the people were thereby settled as one.", idiomatic: "He carried on that quiet rule; the people were at peace." },
  { zh: "」----1春，發長安六百里內男女十四萬六千人城長安，三十日罷。", literal: "” ----1 In spring, within six hundred li of Chang'an, one hundred forty-six thousand men and women were mobilized to wall Chang'an; after thirty days they were dismissed.", idiomatic: "” ----1 In spring, one hundred forty-six thousand men and women within six hundred li of Chang'an were mobilized to wall the city; after thirty days they were dismissed." },
  { zh: "----2以宗室女為公主，嫁匈奴冒頓單于。", literal: "----2 A daughter of the imperial clan was made a princess and married to Maodun, chanyu of the Xiongnu.", idiomatic: "----2 An imperial clanswoman was made a princess and married to Maodun, chanyu of the Xiongnu." },
  { zh: "是時，冒頓方強，為書，使使遺高后，辭極褻嫚。", literal: "At that time Maodun was just then strong; he wrote a letter and sent an envoy to present it to Empress Gao; the wording was extremely lewd and insulting.", idiomatic: "At that time Maodun was at the height of his power; he wrote a letter and sent an envoy to Empress Gao with wording that was grossly lewd and insulting." },
  { zh: "高后大怒，召將相大臣，議斬其使者，發兵擊之。", literal: "Empress Gao was greatly angered, summoned generals, chancellors, and great ministers, and discussed beheading his envoy and sending troops to attack.", idiomatic: "Empress Gao was furious, summoned generals, chancellors, and ministers, and debated executing the envoy and sending troops to attack." },
  { zh: "樊噲曰：「臣願得十萬眾橫行匈奴中！", literal: "Fan Kuai said, “Your servant wishes to have one hundred thousand men and march at will through the Xiongnu!", idiomatic: "Fan Kuai said, “Give me one hundred thousand men and I will march at will through the Xiongnu!" },
  { zh: "」中郎將季布曰：「噲可斬也！", literal: "” Palace gentleman-general Ji Bu said, “Kuai should be beheaded!", idiomatic: "” Palace gentleman-general Ji Bu said, “Kuai deserves execution!" },
  { zh: "前匈奴圍高帝於平城，漢兵三十二萬，噲為上將軍，不能解圍。", literal: "Formerly the Xiongnu besieged the High Emperor at Pingcheng; Han had three hundred twenty thousand troops and Kuai was supreme general, yet could not break the siege.", idiomatic: "When the Xiongnu besieged the High Emperor at Pingcheng, Han had three hundred twenty thousand troops and Kuai was supreme general, yet could not break the siege." },
  { zh: "今歌吟之聲未絕，傷夷者甫起，而噲欲搖動天下，妄言以十萬眾橫行，是面謾也。", literal: "Now the sound of songs has not yet ceased and the wounded have just risen, yet Kuai wishes to shake All under Heaven and rashly speaks of marching at will with one hundred thousand—this is lying to one's face.", idiomatic: "The songs of victory have barely ended and the wounded have just risen, yet Kuai would shake the realm and boast of marching at will with one hundred thousand—this is bare-faced deceit." },
  { zh: "且夷狄譬如禽獸，得其善言不足喜，惡言不足怒也。", literal: "Moreover the barbarians are like birds and beasts: receiving their fine words is not worth joy, nor their evil words worth anger.", idiomatic: "Moreover barbarians are like birds and beasts: fine words are not worth rejoicing over, nor foul words worth anger." },
  { zh: "」高后曰：「善！", literal: "” Empress Gao said, “Good!", idiomatic: "” Empress Gao said, “Good!" },
  { zh: "」令大謁者張釋報書，深自謙遜以謝之，並遺以車二乘，馬二駟。", literal: "” She ordered Grand Usher Zhang Shi to reply to the letter, deeply humble himself in apology, and also send as gifts two carriages and two teams of four horses.", idiomatic: "” She ordered Grand Usher Zhang Shi to reply with a deeply humble apology and also send two carriages and two teams of four horses as gifts." },
  { zh: "冒頓復使使來謝，曰：「未嘗聞中國禮義，陛下幸而赦之。", literal: "Maodun again sent an envoy to apologize, saying, “I have never heard of the rites and righteousness of China; Your Majesty was gracious and pardoned me.", idiomatic: "Maodun sent another envoy to apologize: “I had never heard of China's rites and righteousness; Your Majesty was gracious to pardon me." },
  { zh: "」因獻馬，遂和親。", literal: "” He then presented horses, and thereupon they made a marriage alliance.", idiomatic: "” He presented horses, and peace through marriage followed." },
  { zh: "----3夏，五月，立閩越君搖為東海王。", literal: "----3 In summer, the fifth month, the Lord of Minyue, Yao, was established as King of Donghai.", idiomatic: "----3 In summer, the fifth month, Lord Yao of Minyue was made King of Donghai." },
  { zh: "搖與無諸，皆越王句踐之後也，從諸侯滅秦，功多，其民便附，故立之。", literal: "Yao and Wuzhu were both descendants of King Goujian of Yue; they followed the feudal lords in destroying Qin, their merit was great, and their people were readily attached—therefore they were established.", idiomatic: "Yao and Wuzhu were both descendants of King Goujian of Yue; they followed the lords in destroying Qin with great merit, and their people were readily loyal—therefore they were enfeoffed." },
  { zh: "都東甌，世號東甌王。", literal: "He made his capital at Dong'ou and for generations was called King of Dong'ou.", idiomatic: "His capital was at Dong'ou; for generations he was called King of Dong'ou." },
  { zh: "----4六月，發諸侯王、列侯徒隸二萬人城長安。", literal: "----4 In the sixth month, twenty thousand convict laborers of feudal kings and marquises were mobilized to wall Chang'an.", idiomatic: "----4 In the sixth month, twenty thousand convict laborers of feudal kings and marquises were mobilized to wall Chang'an." },
  { zh: "----5秋，七月，都廄災。", literal: "----5 In autumn, the seventh month, the imperial stables burned.", idiomatic: "----5 In autumn, the seventh month, the imperial stables burned." },
  { zh: "----6是歲，蜀湔氐反，擊平之。", literal: "----6 That year the Qian Di of Shu Jian rebelled and were struck down and pacified.", idiomatic: "----6 That year the Qian Di of Shu Jian rebelled and were suppressed." },
  { zh: "1冬，十月，立皇后張氏。", literal: "1 In winter, the tenth month, Empress Zhang was established.", idiomatic: "1 In winter, the tenth month, Empress Zhang was installed." },
  { zh: "-{后}-，帝姊魯元公主女也，太后欲為重親，故以配帝。", literal: "-{后}-: she was the daughter of the Emperor's elder sister, Princess Yuan of Lu; the Empress Dowager wished to strengthen kin ties and therefore matched her to the Emperor.", idiomatic: "-{后}-: she was the daughter of the Emperor's elder sister, Princess Yuan of Lu; the Empress Dowager wished to strengthen kin ties and therefore matched her to the Emperor." },
  { zh: "----2春，正月，舉民孝、弟、力田者，復其身。", literal: "----2 In spring, the first month, commoners who were filial, fraternal, and diligent in farming were exempted from corvée and taxes.", idiomatic: "----2 In spring, the first month, commoners noted for filial piety, fraternity, and diligence in farming were exempted from service and taxes." },
  { zh: "----3三月，甲子，皇帝冠，赦天下。", literal: "----3 In the third month, on jiazi, the Emperor performed the capping ceremony and amnestied All under Heaven.", idiomatic: "----3 In the third month, on jiazi, the Emperor came of age and amnestied the realm." },
  { zh: "----4省法令妨吏民者；", literal: "----4 Laws and orders that hindered officials and people were reduced;", idiomatic: "----4 Laws that hindered officials and people were trimmed;" },
  { zh: "除挾書律。", literal: "the law against keeping books was abolished.", idiomatic: "the law against keeping books was abolished." },
  { zh: "----5帝以朝太后於長樂宮及間往，數蹕煩民，乃築覆道於武庫南。", literal: "----5 Because the Emperor went to court before the Empress Dowager at Changle Palace and went there from time to time, the repeated road-clearing troubled the people; he therefore built a covered corridor south of the armory.", idiomatic: "----5 Because the Emperor's visits to pay court to the Empress Dowager at Changle Palace and his occasional trips there repeatedly cleared the streets and troubled the people, he built a covered corridor south of the armory." },
  { zh: "奉常叔孫通諫曰：「此高帝月出遊衣冠之道也，子孫奈何乘宗廟道上行哉！", literal: "Chamberlain for Ceremonials Shusun Tong remonstrated, saying, “This is the road by which the High Emperor went out monthly to tour the spirit garments and caps—how can descendants ride along the road of the ancestral temple!", idiomatic: "Chamberlain for Ceremonials Shusun Tong remonstrated: “This is the road the High Emperor used when he went out monthly to attend the spirit garments and caps—how can descendants travel along the ancestral temple road!" },
  { zh: "」帝懼曰：「急壞之！", literal: "” The Emperor was afraid and said, “Quickly tear it down!", idiomatic: "” The Emperor was alarmed and said, “Tear it down at once!" },
  { zh: "」通曰：「人主無過舉。", literal: "” Tong said, “The Son of Heaven has no mistaken actions.", idiomatic: "” Shusun Tong said, “A ruler makes no mistaken actions." },
  { zh: "今已作，百姓皆知之矣。", literal: "What has already been done, the common people all know of it.", idiomatic: "It is already built and all the common people know of it." },
  { zh: "願陛下為原廟渭北，衣冠月出遊之，益廣宗廟，大孝之本。", literal: "I wish Your Majesty would establish a Yuan temple north of the Wei, and each month bring out the robes and caps to tour it—thereby broadening the ancestral temples; this is the root of great filial piety.", idiomatic: "I wish Your Majesty would establish a Yuan temple north of the Wei and each month bring out the spirit robes and caps to tour it, thereby broadening the ancestral temples—this is the root of great filial piety." },
  { zh: "」上乃詔有司立原廟。", literal: "” The Emperor then decreed the relevant officials to establish the Yuan temple.", idiomatic: "” The Emperor then decreed that the relevant officials establish the Yuan temple." },
  { zh: "::臣光曰：過者，人之所必不免也，惟聖賢為能知而改之。", literal: ":: Your servant Guang says: To err is what no person can avoid; only the sage and worthy can know it and amend it.", idiomatic: ":: Your servant Guang says: Faults are what no one can avoid; only the sage and worthy can recognize them and correct them." },
  { zh: "古之聖王，患其有過而不自知也，故設誹謗之木，置敢諫之鼓，豈畏百姓之聞其過哉！", literal: "The sage kings of old, fearing that they had faults yet did not know them, therefore set up the timber for slander and placed the drum for bold remonstrance—how could they have feared the common people hearing their faults!", idiomatic: "The sage kings of old, fearing they might err yet not know it, set up the timber for slander and placed the drum for bold remonstrance—were they afraid of the people hearing their faults!" },
  { zh: "是以仲虺美成湯曰：「改過不吝。", literal: "Therefore Zhong Hui praised Cheng Tang, saying, “To amend faults without regret.", idiomatic: "Therefore Zhong Hui praised Cheng Tang, saying, “To amend faults without regret." },
  { zh: "」傅說戒高宗曰：「無恥過作非。", literal: "” Fuyue admonished Gaozong, saying, “Be not ashamed of faults and doing wrong.", idiomatic: "” Fuyue admonished Gaozong, saying, “Be not ashamed of faults and doing wrong." },
  { zh: "」由是觀之，則為人君者，固不以無過為賢，而以改過為美也。", literal: "” From this we see that for one who is ruler, it is surely not to have no faults that counts as worthy, but to amend faults that counts as beautiful.", idiomatic: "” From this we see that for a ruler it is surely not to be without fault that is admirable, but to amend faults that is praiseworthy." },
  { zh: "今叔孫通諫孝惠，乃雲「人主無過舉」，是教人君以文過遂非也，豈不繆哉！", literal: "Now when Shusun Tong remonstrated with Emperor Hui, he yet said, “The Son of Heaven has no mistaken actions”—this teaches rulers to gloss over faults and persist in error; is it not absurd!", idiomatic: "Now when Shusun Tong remonstrated with Emperor Hui he said, “A ruler makes no mistaken actions”—this teaches rulers to gloss over faults and persist in error; is that not absurd!" },
  { zh: "----6長樂宮鴻台災。", literal: "----6 The Hong Terrace of Changle Palace caught fire.", idiomatic: "----6 The Hong Terrace of Changle Palace caught fire." },
  { zh: "----7秋，七月，乙亥，未央宮凌室災；", literal: "----7 In autumn, the seventh month, on yihai day, the Ling chamber of Weiyang Palace caught fire;", idiomatic: "----7 In autumn, the seventh month, on yihai day, the Ling chamber of Weiyang Palace caught fire;" },
  { zh: "丙子，織室災。", literal: "on bingzi day, the weaving chamber caught fire.", idiomatic: "on bingzi day, the weaving chamber caught fire." },
  { zh: "----1冬，雷；", literal: "----1 In winter, thunder;", idiomatic: "----1 In winter, thunder;" },
  { zh: "桃李華，棗實。", literal: "peach and plum trees blossomed, and jujubes bore fruit.", idiomatic: "peach and plum trees blossomed, and jujubes bore fruit." },
  { zh: "----2春，正月，復發長安六百里內男女十四萬五千人城長安，三十日罷。", literal: "----2 In spring, the first month, again one hundred forty-five thousand men and women within six hundred li of Chang'an were mobilized to wall Chang'an; after thirty days it ceased.", idiomatic: "----2 In spring, the first month, again one hundred forty-five thousand men and women within six hundred li of Chang'an were mobilized to wall Chang'an; after thirty days the work ceased." },
  { zh: "----3夏，大旱，江河水少，谿谷水絕。", literal: "----3 In summer, great drought; the Yangtze and Yellow rivers had little water, and stream and ravine waters dried up.", idiomatic: "----3 In summer there was great drought; the Yangtze and Yellow rivers ran low, and streams and ravines dried up." },
  { zh: "----4秋，八月，己丑，平陽懿侯曹參薨。", literal: "----4 In autumn, the eighth month, on jichou day, Marquis Yi of Pingyang, Cao Shen, died.", idiomatic: "----4 In autumn, the eighth month, on jichou day, Marquis Yi of Pingyang Cao Shen died." },
  { zh: "----1冬，十月，以王陵為右丞相，陳平為左丞相。", literal: "----1 In winter, the tenth month, Wang Ling was made right chancellor and Chen Ping left chancellor.", idiomatic: "----1 In winter, the tenth month, Wang Ling was made right chancellor and Chen Ping left chancellor." },
  { zh: "----2齊悼惠王肥薨。", literal: "----2 King Daohui of Qi, Fei, died.", idiomatic: "----2 King Daohui of Qi, Fei, died." },
  { zh: "----3夏，留文成侯張良薨。", literal: "----3 In summer, Marquis Wen of Liu, Zhang Liang, died.", idiomatic: "----3 In summer, Marquis Wen of Liu Zhang Liang died." },
  { zh: "----4以周勃為太尉。", literal: "----4 Zhou Bo was made grand commandant.", idiomatic: "----4 Zhou Bo was made grand commandant." },
  { zh: "----1冬，發車騎、材官詣滎陽，太尉灌嬰將。", literal: "----1 In winter, chariots, cavalry, and elite troops were dispatched to Xingyang; Grand Commandant Guan Ying commanded them.", idiomatic: "----1 In winter, chariots, cavalry, and elite troops were sent to Xingyang under Grand Commandant Guan Ying." },
  { zh: "----2春，正月，辛丑朔，日有食之。", literal: "----2 In spring, the first month, on the new moon day xinchou, there was an eclipse of the sun.", idiomatic: "----2 In spring, the first month, on the new moon xinchou, there was a solar eclipse." },
  { zh: "----3夏，五月，丁卯，日有食之，既。", literal: "----3 In summer, the fifth month, on dingmao day, there was an eclipse of the sun, total.", idiomatic: "----3 In summer, the fifth month, on dingmao day, there was a total solar eclipse." },
  { zh: "----4秋，八月，戊寅，帝崩於未央宮。", literal: "----4 In autumn, the eighth month, on wuyin day, the Emperor died in Weiyang Palace.", idiomatic: "----4 In autumn, the eighth month, on wuyin day, the Emperor died in Weiyang Palace." },
  { zh: "大赦天下。", literal: "A general amnesty was proclaimed throughout the realm.", idiomatic: "A general amnesty was proclaimed throughout the realm." },
  { zh: "九月，辛丑，葬安陵。", literal: "In the ninth month, on xinchou day, he was buried at Anling.", idiomatic: "In the ninth month, on xinchou day, he was buried at Anling." },
  { zh: "初，呂太后命張皇后取他人子養之，而殺其母，以為太子。", literal: "At first, Empress Dowager Lü ordered Empress Zhang to take another's child to rear, and killed its mother, making him crown prince.", idiomatic: "Earlier, Empress Dowager Lü ordered Empress Zhang to take another woman's child to rear and killed the mother, making him crown prince." },
  { zh: "既葬，太子即皇帝位，年幼；", literal: "After the burial, the crown prince assumed the imperial throne; he was young;", idiomatic: "After the burial the crown prince took the throne; he was young;" },
  { zh: "太后臨朝稱制。", literal: "the empress dowager presided over court and held the imperial regalia.", idiomatic: "the empress dowager presided over court and ruled in her own name." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
